-- V257: Universal EDI X12 Receiver -- auto-routes to whichever of the 9
-- existing X12-to-FHIR mapping chains matches each file's own detected
-- transaction set (ST01/GS08), so one interface can accept a MIX of
-- transaction sets from a trading partner instead of needing one interface
-- per type.
--
-- Purely additive -- the 9 existing per-type templates
-- (edi-835-to-fhir-sftp, edi-837p-to-fhir-sftp, edi-837i-to-fhir-sftp,
-- edi-270-to-fhir-sftp, edi-271-to-fhir-sftp, edi-276-to-fhir-sftp,
-- edi-277-to-fhir-sftp, edi-278-to-fhir-sftp, edi-834-to-fhir-sftp) are
-- untouched and remain the leaner choice for a single-type feed.
--
-- Architecture (see the approved plan for the full investigation):
--   - Zero new Go code. Built entirely from primitives every one of the 9
--     source templates already uses: enrichment.script (derive), fhir.build
--     (rowsPath), payload.builder, fhir_validation.
--   - switch_case + route_to_step branch-skipping was considered and
--     rejected: confirmed by reading pipelineController.js's savePipeline
--     directly that the "Use Template" flow generates a FRESH UUID per step
--     with no pass that remaps any parent_conditional_step_id reference --
--     the same root-cause class already documented for control.loop's
--     childStepIds. Self-gating branches (see below) avoid this blocker
--     entirely.
--   - Every one of the 9 derive scripts already guards on
--     parsed.transactionSet and returns empty arrays for a non-matching
--     type (835's own derive script was the one exception -- it predates
--     that convention and has been given the same guard here). Every
--     downstream fhir.build already reads rowsPath off those arrays, so a
--     non-matching branch simply builds zero resources -- a safe no-op,
--     not a skipped step.
--   - Two real correctness bugs found and fixed by directly querying the 9
--     live templates before merging, not assumed away:
--       1. outputField collisions -- e.g. message.fhirPatients is reused by
--          8 of the 9 branches; message.fhirOrganization by both 278 and
--          834. Every one of the 29 fhir.build steps' outputField (and
--          every fhir.build step's own step_alias, also reused generically
--          across branches, e.g. build_patient_fhir x8) is renamed with a
--          per-branch suffix here.
--       2. 3 of the 29 fhir.build steps (278's UMO Organization, 834's
--          Sponsor Organization, 835's PaymentReconciliation) built an
--          unconditional resource on every message regardless of type --
--          converted to rowsPath mode against a new 0-or-1-row context
--          array each branch's own derive script now also produces (same
--          convention 278's existing _response_contexts already
--          established). 835's PaymentReconciliation needed its own
--          sourcePaths relocated one level (message.parsedEDI.* ->
--          parsedEDI.*) since its new single row embeds the whole parsed
--          document under one key -- confirmed safe against
--          fhir_build_executor.go's own applyRepeatingGroup/applyFieldRow
--          row-scoping rules before making the change, not assumed.
--
-- pipeline_config's embedded JSON (44 steps total: 3 shared ingestion +
-- 9 derive scripts + 29 fhir.build calls + 3 shared assembly/delivery) was
-- generated programmatically by merging the 9 templates' own CURRENTLY LIVE
-- pipeline_config (the authoritative, already-tested source -- several of
-- the 9 have had multiple superseding migrations, e.g. 837P:
-- V237->V239->V244), never hand-retyped.

INSERT INTO interface_templates
    (id, name, slug, description, category, subcategory, tags, icon, difficulty,
     source_connector_type, source_config_template,
     target_connector_type, target_config_template,
     pipeline_config, message_type,
     required_connection_fields, sanitized_fields, preview_steps,
     estimated_setup_minutes, is_system, is_public, author, usage_count)
VALUES
(
    gen_random_uuid(),
    'EDI X12 Universal Receiver (Auto-Routes to FHIR)',
    'edi-universal-to-fhir-sftp',
    'Poll an SFTP directory for ANY of 9 supported X12 transaction sets (835, 837P, 837I, 270, 271, 276, 277, 278, 834) and automatically build the correct FHIR R4 Bundle for whichever type each file turns out to be -- no per-transaction-set interface needed. Each file''s real transaction set is auto-detected from its own ST01/GS08 envelope (the same mechanism every EDI connector in this system already uses); every one of the 9 mapping chains below is reused verbatim from its own standalone template and runs as a safe no-op for every file that is not its type. A 999 (or any unrecognized) file produces a spec-valid, empty Bundle rather than an error. Best for trading partners that send a MIX of transaction sets through one connection -- for a single-type feed, the leaner per-type template (e.g. "EDI X12 835 to FHIR") remains available and unaffected.',
    'edi',
    null,
    ARRAY['edi','x12','universal','auto-routing','835','837','270','271','276','277','278','834','sftp','fhir'],
    '🌐',
    'advanced',
    'edi_x12_inbound',
    '{"transport":"sftp","remote_path":"/incoming","file_pattern":"*.edi","polling_interval_seconds":300,"after_processing":"archive","transaction_types":["835","837P","837I","270","271","276","277","278","834"]}',
    'sink_outbound',
    '{"enable_logging":true,"enable_validation":true}',
    $pipeline$
{"execution_groups":[{"sequence":5,"label":"Shared Ingestion","description":"Accepts ANY of the 9 mapped X12 transaction sets over SFTP. The real transaction set is auto-detected from each file's own ST01/GS08 -- transaction_types below is informational only, never a filter (see V256).","steps":[{"step_name":"Receive EDI File (SFTP)","step_type":"connector.inbound","sequence":5,"config":{"connectorType":"edi_x12_inbound","config":{"transport":"sftp","remote_path":"/incoming","file_pattern":"*.edi","polling_interval_seconds":300,"after_processing":"archive","transaction_types":["835","837P","837I","270","271","276","277","278","834"]}},"enabled":true,"required":true}]},{"sequence":20,"label":"Shared Parse + Validate","description":"One parse/validate pass regardless of which transaction set the file turns out to be.","steps":[{"step_name":"Parse EDI -> JSON","step_type":"edi.parse","sequence":20,"config":{"sourceField":"raw","outputField":"parsedEDI"},"enabled":true,"required":true},{"step_name":"Validate Against X12 5010","step_type":"edi.validate","sequence":30,"config":{"sourceField":"raw","outputField":"ediValidation","customRules":[]},"enabled":true,"required":false}]},{"sequence":400,"label":"Branch — 270 (edi-270-to-fhir-sftp)","description":"Auto-routes here only when edi.parse detects transaction set \"270\" — every step below is a no-op (produces zero rows/resources) for any other detected type. Reused verbatim from the standalone \"edi-270-to-fhir-sftp\" template.","steps":[{"config":{"script":"\nvar parsed = (input.message && input.message.parsedEDI) || input.parsedEDI || {};\nvar loops = parsed.loops || {};\n\nif (parsed.transactionSet !== \"270\") {\n  return ({ _eligibility_contexts: [] });\n}\n\nfunction arr(v) {\n  if (!v) return [];\n  return Array.isArray(v) ? v : [v];\n}\nfunction first(v) {\n  var a = arr(v);\n  return a.length > 0 ? a[0] : {};\n}\nfunction genderToFHIR(code) {\n  if (code === \"M\") return \"male\";\n  if (code === \"F\") return \"female\";\n  return \"unknown\";\n}\nfunction relationshipToFHIR(code) {\n  var map = { \"18\": \"self\", \"01\": \"spouse\", \"19\": \"child\", \"20\": \"employee\" };\n  return map[code] || \"other\";\n}\n\nvar infoSourceLevels = arr(loops[\"2000A\"]);\nvar contexts = [];\nvar nowIso = new Date().toISOString();\n\nfor (var srcIdx = 0; srcIdx < infoSourceLevels.length; srcIdx++) {\n  var srcLevel = infoSourceLevels[srcIdx];\n  var srcNM1 = ((srcLevel.loops || {})[\"2100A\"] || {}).NM1 || {};\n  var payerInfo = { payer_id: srcNM1.identificationCode || \"\", name: srcNM1.nameLastOrOrganizationName || \"\" };\n\n  var receiverLevels = arr((srcLevel.loops || {})[\"2000B\"]);\n  for (var rcvIdx = 0; rcvIdx < receiverLevels.length; rcvIdx++) {\n    var rcvLevel = receiverLevels[rcvIdx];\n    var rcvNM1 = ((rcvLevel.loops || {})[\"2100B\"] || {}).NM1 || {};\n    var providerInfo = { npi: rcvNM1.identificationCode || \"\", name: rcvNM1.nameLastOrOrganizationName || \"\" };\n\n    var subscriberLevels = arr((rcvLevel.loops || {})[\"2000C\"]);\n    for (var subIdx = 0; subIdx < subscriberLevels.length; subIdx++) {\n      var subLevel = subscriberLevels[subIdx];\n      var sub2100C = (subLevel.loops || {})[\"2100C\"] || {};\n      var subNM1 = sub2100C.NM1 || {};\n      var subDMG = sub2100C.DMG || {};\n      var subscriberInfo = {\n        member_id: subNM1.identificationCode || \"\",\n        first_name: subNM1.nameFirst || \"\",\n        last_name: subNM1.nameLastOrOrganizationName || \"\",\n        dob: subDMG.birthDate || \"\",\n        gender_fhir: genderToFHIR(subDMG.genderCode),\n      };\n\n      var dependentLevels = arr((subLevel.loops || {})[\"2000D\"]);\n\n      function pushContext(patientInfo, relationshipFHIR, eqLoops) {\n        var items = [];\n        var eqList = arr(eqLoops);\n        for (var i = 0; i < eqList.length; i++) {\n          var eq = eqList[i].EQ || {};\n          if (!eq.serviceTypeCode) continue;\n          items.push({ category_code: eq.serviceTypeCode });\n        }\n        contexts.push({\n          patient_info: patientInfo,\n          subscriber_info: subscriberInfo,\n          payer_info: payerInfo,\n          provider_info: providerInfo,\n          relationship_fhir: relationshipFHIR,\n          created_at: nowIso,\n          request_identifier: subLevel.TRN ? subLevel.TRN.checkOrEFTTraceNumber : \"\",\n          items: items,\n        });\n      }\n\n      if (dependentLevels.length === 0) {\n        pushContext(subscriberInfo, \"self\", sub2100C.loops ? sub2100C.loops[\"2110C\"] : []);\n      } else {\n        for (var depIdx = 0; depIdx < dependentLevels.length; depIdx++) {\n          var depLevel = dependentLevels[depIdx];\n          var dep2100D = (depLevel.loops || {})[\"2100D\"] || {};\n          var depNM1 = dep2100D.NM1 || {};\n          var depDMG = dep2100D.DMG || {};\n          var depINS = dep2100D.INS || {};\n          var dependentInfo = {\n            member_id: depNM1.identificationCode || subscriberInfo.member_id,\n            first_name: depNM1.nameFirst || \"\",\n            last_name: depNM1.nameLastOrOrganizationName || \"\",\n            dob: depDMG.birthDate || \"\",\n            gender_fhir: genderToFHIR(depDMG.genderCode),\n          };\n          pushContext(dependentInfo, relationshipToFHIR(depINS.individualRelationshipCode), dep2100D.loops ? dep2100D.loops[\"2110D\"] : []);\n        }\n      }\n    }\n  }\n}\n\nreturn ({ _eligibility_contexts: contexts });\n"},"enabled":true,"required":true,"sequence":401,"step_name":"Derive 270 Eligibility Contexts","step_type":"enrichment.script","step_alias":"derive_270_eligibility_contexts","description":"Pure data reshaping only -- this engine transforms X12 <-> FHIR, it never decides eligibility facts. Flattens 270's information-source/receiver/subscriber/dependent structure into one flat array (_eligibility_contexts), one row per patient (subscriber or her dependent), so the fhir.build steps below can build one Patient/CoverageEligibilityRequest per patient declaratively via rowsPath."},{"config":{"fields":[{"valueMap":{"prefix":"organization-payer-"},"transform":"string_prefix","sourcePath":"payer_info.payer_id","targetPath":"id"},{"targetPath":"active","literalValue":"true"},{"sourcePath":"payer_info.name","targetPath":"name"}],"profile":"base","version":"R4","rowsPath":"steps.derive_270_eligibility_contexts.step_output._eligibility_contexts","outputField":"message.fhirPayerOrganizations_270","resourceType":"Organization"},"enabled":true,"required":true,"sequence":402,"step_name":"Build Payer Organization","step_type":"fhir.build","step_alias":"build_payer_organization_fhir_270","description":"Builds the information source (2100A, the payer) as a FHIR Organization resource per eligibility context."},{"config":{"fields":[{"valueMap":{"prefix":"organization-provider-"},"transform":"string_prefix","sourcePath":"provider_info.npi","targetPath":"id"},{"targetPath":"active","literalValue":"true"},{"sourcePath":"provider_info.name","targetPath":"name"}],"profile":"base","version":"R4","rowsPath":"steps.derive_270_eligibility_contexts.step_output._eligibility_contexts","outputField":"message.fhirProviderOrganizations_270","resourceType":"Organization"},"enabled":true,"required":true,"sequence":403,"step_name":"Build Provider Organization","step_type":"fhir.build","step_alias":"build_provider_organization_fhir_270","description":"Builds the information receiver (2100B, the provider) as a FHIR Organization resource per eligibility context."},{"config":{"fields":[{"sourcePath":"patient_info.member_id","targetPath":"id"},{"targetPath":"identifier[0].system","literalValue":"http://ezhealthkonnect.local/x12-member-id"},{"sourcePath":"patient_info.member_id","targetPath":"identifier[0].value"},{"sourcePath":"patient_info.last_name","targetPath":"name[0].family"},{"sourcePath":"patient_info.first_name","targetPath":"name[0].given[0]"},{"transform":"x12_date_to_fhir_date","sourcePath":"patient_info.dob","targetPath":"birthDate"},{"sourcePath":"patient_info.gender_fhir","targetPath":"gender"}],"profile":"base","version":"R4","rowsPath":"steps.derive_270_eligibility_contexts.step_output._eligibility_contexts","outputField":"message.fhirPatients_270","resourceType":"Patient"},"enabled":true,"required":true,"sequence":404,"step_name":"Build Patient","step_type":"fhir.build","step_alias":"build_patient_fhir_270","description":"Builds one FHIR Patient resource per eligibility context -- the patient is the subscriber when asking about herself, or the dependent (2100D) otherwise."},{"config":{"fields":[{"valueMap":{"prefix":"eligibility-request-"},"transform":"string_prefix","sourcePath":"request_identifier","targetPath":"id"},{"targetPath":"status","literalValue":"active"},{"targetPath":"purpose[0]","literalValue":"benefits"},{"valueMap":{"prefix":"Patient/"},"transform":"string_prefix","sourcePath":"patient_info.member_id","targetPath":"patient.reference"},{"sourcePath":"created_at","targetPath":"created"},{"targetPath":"provider.identifier.system","literalValue":"http://hl7.org/fhir/sid/us-npi"},{"sourcePath":"provider_info.npi","targetPath":"provider.identifier.value"},{"targetPath":"insurer.identifier.system","literalValue":"http://ezhealthkonnect.local/x12-payer-id"},{"sourcePath":"payer_info.payer_id","targetPath":"insurer.identifier.value"}],"profile":"base","version":"R4","rowsPath":"steps.derive_270_eligibility_contexts.step_output._eligibility_contexts","outputField":"message.fhirCoverageEligibilityRequests_270","resourceType":"CoverageEligibilityRequest","repeatingGroups":[{"fields":[{"targetPath":"category.coding[0].system","literalValue":"https://codesystem.x12.org/005010/1365"},{"sourcePath":"category_code","targetPath":"category.coding[0].code"}],"rowsPath":"items","targetPath":"item"}]},"enabled":true,"required":true,"sequence":405,"step_name":"Build CoverageEligibilityRequest","step_type":"fhir.build","step_alias":"build_coverage_eligibility_request_fhir_270","description":"Builds one FHIR CoverageEligibilityRequest resource per eligibility context. item[] built via repeatingGroups off that patient's own EQ inquiries (one row per 2110C/2110D EQ occurrence)."}]},{"sequence":500,"label":"Branch — 271 (edi-271-to-fhir-sftp)","description":"Auto-routes here only when edi.parse detects transaction set \"271\" — every step below is a no-op (produces zero rows/resources) for any other detected type. Reused verbatim from the standalone \"edi-271-to-fhir-sftp\" template.","steps":[{"config":{"script":"\nvar parsed = (input.message && input.message.parsedEDI) || input.parsedEDI || {};\nvar loops = parsed.loops || {};\n\nif (parsed.transactionSet !== \"271\") {\n  return ({ _coverage_contexts: [] });\n}\n\nfunction arr(v) {\n  if (!v) return [];\n  return Array.isArray(v) ? v : [v];\n}\n\nvar infoSourceLevels = arr(loops[\"2000A\"]);\nvar contexts = [];\nvar nowIso = new Date().toISOString();\n\nfor (var srcIdx = 0; srcIdx < infoSourceLevels.length; srcIdx++) {\n  var srcLevel = infoSourceLevels[srcIdx];\n  var srcNM1 = ((srcLevel.loops || {})[\"2100A\"] || {}).NM1 || {};\n  var payerInfo = { payer_id: srcNM1.identificationCode || \"\", name: srcNM1.nameLastOrOrganizationName || \"\" };\n\n  var receiverLevels = arr((srcLevel.loops || {})[\"2000B\"]);\n  for (var rcvIdx = 0; rcvIdx < receiverLevels.length; rcvIdx++) {\n    var rcvLevel = receiverLevels[rcvIdx];\n\n    var subscriberLevels = arr((rcvLevel.loops || {})[\"2000C\"]);\n    for (var subIdx = 0; subIdx < subscriberLevels.length; subIdx++) {\n      var subLevel = subscriberLevels[subIdx];\n      var sub2100C = (subLevel.loops || {})[\"2100C\"] || {};\n      var subNM1 = sub2100C.NM1 || {};\n      var subscriberInfo = {\n        member_id: subNM1.identificationCode || \"\",\n        first_name: subNM1.nameFirst || \"\",\n        last_name: subNM1.nameLastOrOrganizationName || \"\",\n      };\n\n      var dependentLevels = arr((subLevel.loops || {})[\"2000D\"]);\n\n      // Builds the item[] rows (one per real 2110C/2110D EB occurrence) that\n      // sit INSIDE the one insurance[] entry -- FHIR's own shape is ONE\n      // coverage (insurance[]) carrying MULTIPLE reported benefits (item[]),\n      // not one insurance entry per benefit fact.\n      function buildInsuranceItemRows(eb2110List) {\n        var out = [];\n        var ebList = arr(eb2110List);\n        for (var i = 0; i < ebList.length; i++) {\n          var eb = ebList[i].EB || {};\n          if (!eb.eligibilityBenefitInformationCode) continue;\n          var benefits = [{\n            eb_code: eb.eligibilityBenefitInformationCode,\n            allowed_amount: eb.monetaryAmount || \"\",\n            plan_description: eb.planCoverageDescription || \"\",\n          }];\n          out.push({ category_code: eb.serviceTypeCode || \"\", benefits: benefits });\n        }\n        return out;\n      }\n\n      function pushContext(patientInfo, requestId, aaaList, eb2110List) {\n        var rejections = arr(aaaList);\n        var isRejected = rejections.length > 0;\n        var errorItems = [];\n        for (var i = 0; i < rejections.length; i++) {\n          errorItems.push({ reject_reason_code: rejections[i].rejectReasonCode || \"\" });\n        }\n        // \"insurance\" is a 0-or-1-element array (this mapping reports exactly\n        // one real-world coverage per patient) so the fhir.build repeatingGroup\n        // naturally produces zero insurance[] entries for a rejected patient --\n        // the same \"empty rowsPath array -> zero repeatingGroup rows\" convention\n        // 837's own diagnosis/item/careTeam repeatingGroups already rely on,\n        // rather than a separate conditional mechanism.\n        var insurance = isRejected ? [] : [{\n          member_id: patientInfo.member_id,\n          items: buildInsuranceItemRows(eb2110List),\n        }];\n        contexts.push({\n          patient_info: patientInfo,\n          payer_info: payerInfo,\n          created_at: nowIso,\n          request_identifier: requestId || \"\",\n          outcome: isRejected ? \"error\" : \"complete\",\n          insurance: insurance,\n          error_items: errorItems,\n        });\n      }\n\n      if (dependentLevels.length === 0) {\n        pushContext(\n          subscriberInfo,\n          subLevel.TRN ? subLevel.TRN.checkOrEFTTraceNumber : \"\",\n          sub2100C.AAA,\n          sub2100C.loops ? sub2100C.loops[\"2110C\"] : []\n        );\n      } else {\n        for (var depIdx = 0; depIdx < dependentLevels.length; depIdx++) {\n          var depLevel = dependentLevels[depIdx];\n          var dep2100D = (depLevel.loops || {})[\"2100D\"] || {};\n          var depNM1 = dep2100D.NM1 || {};\n          var dependentInfo = {\n            member_id: depNM1.identificationCode || subscriberInfo.member_id,\n            first_name: depNM1.nameFirst || \"\",\n            last_name: depNM1.nameLastOrOrganizationName || \"\",\n          };\n          pushContext(\n            dependentInfo,\n            depLevel.TRN ? depLevel.TRN.checkOrEFTTraceNumber : \"\",\n            dep2100D.AAA,\n            dep2100D.loops ? dep2100D.loops[\"2110D\"] : []\n          );\n        }\n      }\n    }\n  }\n}\n\nreturn ({ _coverage_contexts: contexts });\n"},"enabled":true,"required":true,"sequence":501,"step_name":"Derive 271 Eligibility Contexts","step_type":"enrichment.script","step_alias":"derive_271_eligibility_contexts","description":"Pure data reshaping only -- this engine transforms X12 <-> FHIR, it never decides eligibility facts. Flattens 271's subscriber/dependent structure into one flat array (_coverage_contexts), pre-computing the complete/error outcome directly from whether that patient's own 2100C/2100D carries an AAA rejection segment -- a structural fact already in the message, never invented."},{"config":{"fields":[{"sourcePath":"patient_info.member_id","targetPath":"id"},{"targetPath":"identifier[0].system","literalValue":"http://ezhealthkonnect.local/x12-member-id"},{"sourcePath":"patient_info.member_id","targetPath":"identifier[0].value"},{"sourcePath":"patient_info.last_name","targetPath":"name[0].family"},{"sourcePath":"patient_info.first_name","targetPath":"name[0].given[0]"}],"profile":"base","version":"R4","rowsPath":"steps.derive_271_eligibility_contexts.step_output._coverage_contexts","outputField":"message.fhirPatients_271","resourceType":"Patient"},"enabled":true,"required":true,"sequence":502,"step_name":"Build Patient","step_type":"fhir.build","step_alias":"build_patient_fhir_271","description":"Builds one FHIR Patient resource per coverage context -- the patient is the subscriber when the response is about herself, or the dependent (2100D) otherwise."},{"config":{"fields":[{"valueMap":{"prefix":"eligibility-response-"},"transform":"string_prefix","sourcePath":"request_identifier","targetPath":"id"},{"targetPath":"status","literalValue":"active"},{"targetPath":"purpose[0]","literalValue":"benefits"},{"valueMap":{"prefix":"Patient/"},"transform":"string_prefix","sourcePath":"patient_info.member_id","targetPath":"patient.reference"},{"sourcePath":"created_at","targetPath":"created"},{"sourcePath":"outcome","targetPath":"outcome"},{"targetPath":"request.identifier.system","literalValue":"http://ezhealthkonnect.local/x12-trace-number"},{"sourcePath":"request_identifier","targetPath":"request.identifier.value"},{"targetPath":"insurer.identifier.system","literalValue":"http://ezhealthkonnect.local/x12-payer-id"},{"sourcePath":"payer_info.payer_id","targetPath":"insurer.identifier.value"}],"profile":"base","version":"R4","rowsPath":"steps.derive_271_eligibility_contexts.step_output._coverage_contexts","outputField":"message.fhirCoverageEligibilityResponses_271","resourceType":"CoverageEligibilityResponse","repeatingGroups":[{"fields":[{"targetPath":"coverage.identifier.system","literalValue":"http://ezhealthkonnect.local/x12-member-id"},{"sourcePath":"member_id","targetPath":"coverage.identifier.value"}],"rowsPath":"insurance","targetPath":"insurance","repeatingGroups":[{"fields":[{"targetPath":"category.coding[0].system","literalValue":"https://codesystem.x12.org/005010/1365"},{"sourcePath":"category_code","targetPath":"category.coding[0].code"}],"rowsPath":"items","targetPath":"item","repeatingGroups":[{"fields":[{"targetPath":"type.coding[0].system","literalValue":"https://codesystem.x12.org/005010/1338"},{"sourcePath":"eb_code","targetPath":"type.coding[0].code"},{"sourcePath":"allowed_amount","targetPath":"allowedMoney.value"},{"targetPath":"allowedMoney.currency","literalValue":"USD"}],"rowsPath":"benefits","targetPath":"benefit"}]}]},{"fields":[{"targetPath":"code.coding[0].system","literalValue":"https://codesystem.x12.org/005010/901"},{"sourcePath":"reject_reason_code","targetPath":"code.coding[0].code"}],"rowsPath":"error_items","targetPath":"error"}]},"enabled":true,"required":true,"sequence":503,"step_name":"Build CoverageEligibilityResponse","step_type":"fhir.build","step_alias":"build_coverage_eligibility_response_fhir_271","description":"Builds one FHIR CoverageEligibilityResponse resource per coverage context. insurance[].item[].benefit[] built via nested repeatingGroups off that patient's own EB-derived benefit facts (empty for a rejected patient, whose outcome=error and error[] carry the real AAA reject reason instead)."}]},{"sequence":600,"label":"Branch — 276 (edi-276-to-fhir-sftp)","description":"Auto-routes here only when edi.parse detects transaction set \"276\" — every step below is a no-op (produces zero rows/resources) for any other detected type. Reused verbatim from the standalone \"edi-276-to-fhir-sftp\" template.","steps":[{"config":{"script":"\nvar parsed = (input.message && input.message.parsedEDI) || input.parsedEDI || {};\nvar loops = parsed.loops || {};\n\nif (parsed.transactionSet !== \"276\") {\n  return ({ _claim_status_requests: [] });\n}\n\nfunction arr(v) {\n  if (!v) return [];\n  return Array.isArray(v) ? v : [v];\n}\nfunction first(v) {\n  var a = arr(v);\n  return a.length > 0 ? a[0] : {};\n}\nfunction genderToFHIR(code) {\n  if (code === \"M\") return \"male\";\n  if (code === \"F\") return \"female\";\n  return \"unknown\";\n}\n\nvar infoSourceLevels = arr(loops[\"2000A\"]);\nvar contexts = [];\nvar nowIso = new Date().toISOString();\n\nfor (var srcIdx = 0; srcIdx < infoSourceLevels.length; srcIdx++) {\n  var srcLevel = infoSourceLevels[srcIdx];\n  var srcNM1 = ((srcLevel.loops || {})[\"2100A\"] || {}).NM1 || {};\n  var payerInfo = { payer_id: srcNM1.identificationCode || \"\", name: srcNM1.nameLastOrOrganizationName || \"\" };\n\n  var receiverLevels = arr((srcLevel.loops || {})[\"2000B\"]);\n  for (var rcvIdx = 0; rcvIdx < receiverLevels.length; rcvIdx++) {\n    var rcvLevel = receiverLevels[rcvIdx];\n\n    var providerLevels = arr((rcvLevel.loops || {})[\"2000C\"]);\n    for (var provIdx = 0; provIdx < providerLevels.length; provIdx++) {\n      var provLevel = providerLevels[provIdx];\n      var provNM1 = ((provLevel.loops || {})[\"2100C\"] || {}).NM1 || {};\n      var providerInfo = { npi: provNM1.identificationCode || \"\", name: provNM1.nameLastOrOrganizationName || \"\" };\n\n      function pushContext(patientInfo, claim) {\n        // REF has maxUse=\">1\" in its own segment definition, so the real\n        // parser always wraps it as an array (same reason STC needs\n        // first() in the 277 derive script) -- take the first occurrence\n        // even when only one REF is actually present.\n        var ref = first(claim.REF);\n        contexts.push({\n          patient_info: patientInfo,\n          payer_info: payerInfo,\n          provider_info: providerInfo,\n          created_at: nowIso,\n          request_identifier: claim.TRN ? claim.TRN.checkOrEFTTraceNumber : \"\",\n          patient_control_number: ref.referenceIdentification || \"\",\n        });\n      }\n\n      var subscriberLevels = arr((provLevel.loops || {})[\"2000D\"]);\n      for (var subIdx = 0; subIdx < subscriberLevels.length; subIdx++) {\n        var subLevel = subscriberLevels[subIdx];\n        var sub2100D = (subLevel.loops || {})[\"2100D\"] || {};\n        var subNM1 = sub2100D.NM1 || {};\n        var subDMG = sub2100D.DMG || {};\n        var subscriberInfo = {\n          member_id: subNM1.identificationCode || \"\",\n          first_name: subNM1.nameFirst || \"\",\n          last_name: subNM1.nameLastOrOrganizationName || \"\",\n          dob: subDMG.birthDate || \"\",\n          gender_fhir: genderToFHIR(subDMG.genderCode),\n        };\n\n        var claim2200D = arr(sub2100D.loops ? sub2100D.loops[\"2200D\"] : []);\n        for (var c = 0; c < claim2200D.length; c++) {\n          pushContext(subscriberInfo, claim2200D[c]);\n        }\n\n        // \"2000E\" is a SIBLING of \"2100D\" within 2000D's OWN \"loops\" map\n        // (matching Dependent's real HL parent being the Subscriber, not\n        // nested inside 2100D's own loops, which only holds \"2200D\") —\n        // read from subLevel (the 2000D instance itself), not sub2100D.\n        var dependentLevels = arr(subLevel.loops ? subLevel.loops[\"2000E\"] : []);\n        for (var depIdx = 0; depIdx < dependentLevels.length; depIdx++) {\n          var depLevel = dependentLevels[depIdx];\n          var dep2100E = (depLevel.loops || {})[\"2100E\"] || {};\n          var depNM1 = dep2100E.NM1 || {};\n          var depDMG = dep2100E.DMG || {};\n          var dependentInfo = {\n            member_id: depNM1.identificationCode || subscriberInfo.member_id,\n            first_name: depNM1.nameFirst || \"\",\n            last_name: depNM1.nameLastOrOrganizationName || \"\",\n            dob: depDMG.birthDate || \"\",\n            gender_fhir: genderToFHIR(depDMG.genderCode),\n          };\n          var claim2200E = arr(dep2100E.loops ? dep2100E.loops[\"2200E\"] : []);\n          for (var d = 0; d < claim2200E.length; d++) {\n            pushContext(dependentInfo, claim2200E[d]);\n          }\n        }\n      }\n    }\n  }\n}\n\nreturn ({ _claim_status_requests: contexts });\n"},"enabled":true,"required":true,"sequence":601,"step_name":"Derive 276 Claim Status Requests","step_type":"enrichment.script","step_alias":"derive_276_claim_status_requests","description":"Pure structural reshaping only -- this engine transforms X12 <-> FHIR, it never decides claim status facts (a 276 is an inquiry, it carries none). Flattens 276's payer/clearinghouse/provider/subscriber/dependent structure into one flat array (_claim_status_requests), one row per claim status inquiry (subscriber's own claim or a dependent's own claim), so the fhir.build steps below can build one Task per inquiry declaratively via rowsPath."},{"config":{"fields":[{"valueMap":{"prefix":"organization-payer-"},"transform":"string_prefix","sourcePath":"payer_info.payer_id","targetPath":"id"},{"targetPath":"active","literalValue":"true"},{"sourcePath":"payer_info.name","targetPath":"name"}],"profile":"base","version":"R4","rowsPath":"steps.derive_276_claim_status_requests.step_output._claim_status_requests","outputField":"message.fhirPayerOrganizations_276","resourceType":"Organization"},"enabled":true,"required":true,"sequence":602,"step_name":"Build Payer Organization","step_type":"fhir.build","step_alias":"build_payer_organization_fhir_276","description":"Builds the payer (2100A, the information source) as a FHIR Organization resource per claim status request context."},{"config":{"fields":[{"sourcePath":"patient_info.member_id","targetPath":"id"},{"targetPath":"identifier[0].system","literalValue":"http://ezhealthkonnect.local/x12-member-id"},{"sourcePath":"patient_info.member_id","targetPath":"identifier[0].value"},{"sourcePath":"patient_info.last_name","targetPath":"name[0].family"},{"sourcePath":"patient_info.first_name","targetPath":"name[0].given[0]"},{"transform":"x12_date_to_fhir_date","sourcePath":"patient_info.dob","targetPath":"birthDate"},{"sourcePath":"patient_info.gender_fhir","targetPath":"gender"}],"profile":"base","version":"R4","rowsPath":"steps.derive_276_claim_status_requests.step_output._claim_status_requests","outputField":"message.fhirPatients_276","resourceType":"Patient"},"enabled":true,"required":true,"sequence":603,"step_name":"Build Patient","step_type":"fhir.build","step_alias":"build_patient_fhir_276","description":"Builds one FHIR Patient resource per context -- the patient is the subscriber when asking about/reporting on herself, or the dependent (2100D/2100E) otherwise."},{"config":{"fields":[{"valueMap":{"prefix":"claim-status-request-"},"transform":"string_prefix","sourcePath":"request_identifier","targetPath":"id"},{"targetPath":"status","literalValue":"requested"},{"targetPath":"intent","literalValue":"order"},{"targetPath":"code.coding[0].system","literalValue":"http://terminology.hl7.org/CodeSystem/task-code"},{"targetPath":"code.coding[0].code","literalValue":"fulfill"},{"targetPath":"description","literalValue":"Health Care Claim Status Request (X12 276)"},{"valueMap":{"prefix":"Patient/"},"transform":"string_prefix","sourcePath":"patient_info.member_id","targetPath":"for.reference"},{"sourcePath":"created_at","targetPath":"authoredOn"},{"targetPath":"requester.identifier.system","literalValue":"http://hl7.org/fhir/sid/us-npi"},{"sourcePath":"provider_info.npi","targetPath":"requester.identifier.value"},{"targetPath":"owner.identifier.system","literalValue":"http://ezhealthkonnect.local/x12-payer-id"},{"sourcePath":"payer_info.payer_id","targetPath":"owner.identifier.value"},{"targetPath":"identifier[0].system","literalValue":"http://ezhealthkonnect.local/x12-patient-control-number"},{"sourcePath":"patient_control_number","targetPath":"identifier[0].value"}],"profile":"base","version":"R4","rowsPath":"steps.derive_276_claim_status_requests.step_output._claim_status_requests","outputField":"message.fhirTasks_276","resourceType":"Task"},"enabled":true,"required":true,"sequence":604,"step_name":"Build Task","step_type":"fhir.build","step_alias":"build_task_fhir_276","description":"Builds one FHIR Task resource per claim status request -- a claim status REQUEST is an administrative 'please tell me the status of this claim' ask, which FHIR's own Task resource models directly (status=requested, intent=order)."}]},{"sequence":700,"label":"Branch — 277 (edi-277-to-fhir-sftp)","description":"Auto-routes here only when edi.parse detects transaction set \"277\" — every step below is a no-op (produces zero rows/resources) for any other detected type. Reused verbatim from the standalone \"edi-277-to-fhir-sftp\" template.","steps":[{"config":{"script":"\nvar parsed = (input.message && input.message.parsedEDI) || input.parsedEDI || {};\nvar loops = parsed.loops || {};\n\nif (parsed.transactionSet !== \"277\") {\n  return ({ _claim_status_responses: [] });\n}\n\nfunction arr(v) {\n  if (!v) return [];\n  return Array.isArray(v) ? v : [v];\n}\nfunction first(v) {\n  var a = arr(v);\n  return a.length > 0 ? a[0] : {};\n}\nfunction genderToFHIR(code) {\n  if (code === \"M\") return \"male\";\n  if (code === \"F\") return \"female\";\n  return \"unknown\";\n}\nfunction stcCategoryToTaskStatus(code) {\n  var map = {\n    \"A1\": \"received\", \"A2\": \"accepted\", \"A3\": \"rejected\", \"A4\": \"rejected\",\n    \"A6\": \"rejected\", \"A7\": \"rejected\", \"A8\": \"rejected\",\n    \"F0\": \"completed\", \"F1\": \"completed\", \"F2\": \"completed\", \"F3\": \"completed\",\n    \"P0\": \"in-progress\", \"P1\": \"in-progress\", \"P2\": \"in-progress\",\n    \"P3\": \"in-progress\", \"P4\": \"in-progress\", \"P5\": \"in-progress\"\n  };\n  return map[code] || \"in-progress\";\n}\n\nvar infoSourceLevels = arr(loops[\"2000A\"]);\nvar contexts = [];\n\nfor (var srcIdx = 0; srcIdx < infoSourceLevels.length; srcIdx++) {\n  var srcLevel = infoSourceLevels[srcIdx];\n  var srcNM1 = ((srcLevel.loops || {})[\"2100A\"] || {}).NM1 || {};\n  var payerInfo = { payer_id: srcNM1.identificationCode || \"\", name: srcNM1.nameLastOrOrganizationName || \"\" };\n\n  var receiverLevels = arr((srcLevel.loops || {})[\"2000B\"]);\n  for (var rcvIdx = 0; rcvIdx < receiverLevels.length; rcvIdx++) {\n    var rcvLevel = receiverLevels[rcvIdx];\n\n    var providerLevels = arr((rcvLevel.loops || {})[\"2000C\"]);\n    for (var provIdx = 0; provIdx < providerLevels.length; provIdx++) {\n      var provLevel = providerLevels[provIdx];\n      var provNM1 = ((provLevel.loops || {})[\"2100C\"] || {}).NM1 || {};\n      var providerInfo = { npi: provNM1.identificationCode || \"\", name: provNM1.nameLastOrOrganizationName || \"\" };\n\n      function pushContext(patientInfo, claim) {\n        // STC and REF both have maxUse=\">1\" in their own segment\n        // definitions, so the real parser always wraps them as arrays —\n        // take the first (claim-level overall status / control number)\n        // occurrence, even when only one is actually present.\n        var stc = first(claim.STC).healthCareClaimStatus || {};\n        var ref = first(claim.REF);\n        contexts.push({\n          patient_info: patientInfo,\n          payer_info: payerInfo,\n          provider_info: providerInfo,\n          response_identifier: claim.TRN ? claim.TRN.checkOrEFTTraceNumber : \"\",\n          payer_claim_control_number: ref.referenceIdentification || \"\",\n          task_status: stcCategoryToTaskStatus(stc.categoryCode || \"\"),\n          status_category_code: stc.categoryCode || \"\",\n          status_code: stc.statusCode || \"\",\n        });\n      }\n\n      var subscriberLevels = arr((provLevel.loops || {})[\"2000D\"]);\n      for (var subIdx = 0; subIdx < subscriberLevels.length; subIdx++) {\n        var subLevel = subscriberLevels[subIdx];\n        var sub2100D = (subLevel.loops || {})[\"2100D\"] || {};\n        var subNM1 = sub2100D.NM1 || {};\n        var subscriberInfo = { member_id: subNM1.identificationCode || \"\", first_name: subNM1.nameFirst || \"\", last_name: subNM1.nameLastOrOrganizationName || \"\", gender_fhir: \"unknown\" };\n\n        var claim2200D = arr(sub2100D.loops ? sub2100D.loops[\"2200D\"] : []);\n        for (var c = 0; c < claim2200D.length; c++) {\n          pushContext(subscriberInfo, claim2200D[c]);\n        }\n\n        // \"2000E\" is a SIBLING of \"2100D\" within 2000D's OWN \"loops\" map\n        // (matching Dependent's real HL parent being the Subscriber, not\n        // nested inside 2100D's own loops, which only holds \"2200D\") —\n        // read from subLevel (the 2000D instance itself), not sub2100D.\n        var dependentLevels = arr(subLevel.loops ? subLevel.loops[\"2000E\"] : []);\n        for (var depIdx = 0; depIdx < dependentLevels.length; depIdx++) {\n          var depLevel = dependentLevels[depIdx];\n          var dep2100E = (depLevel.loops || {})[\"2100E\"] || {};\n          var depNM1 = dep2100E.NM1 || {};\n          var dependentInfo = { member_id: depNM1.identificationCode || subscriberInfo.member_id, first_name: depNM1.nameFirst || \"\", last_name: depNM1.nameLastOrOrganizationName || \"\", gender_fhir: \"unknown\" };\n          var claim2200E = arr(dep2100E.loops ? dep2100E.loops[\"2200E\"] : []);\n          for (var d = 0; d < claim2200E.length; d++) {\n            pushContext(dependentInfo, claim2200E[d]);\n          }\n        }\n      }\n    }\n  }\n}\n\nreturn ({ _claim_status_responses: contexts });\n"},"enabled":true,"required":true,"sequence":701,"step_name":"Derive 277 Claim Status Responses","step_type":"enrichment.script","step_alias":"derive_277_claim_status_responses","description":"Pure structural reshaping only -- this engine transforms X12 <-> FHIR, it never decides claim status facts. Flattens 277's payer/clearinghouse/provider/subscriber/dependent structure into one flat array (_claim_status_responses), one row per reported claim status, translating the X12 STC category code into FHIR's own Task.status vocabulary along the way (a code-system translation, same class as 270/271's own gender/relationship mapping) so the fhir.build steps below can build one Task per response declaratively via rowsPath."},{"config":{"fields":[{"valueMap":{"prefix":"organization-payer-"},"transform":"string_prefix","sourcePath":"payer_info.payer_id","targetPath":"id"},{"targetPath":"active","literalValue":"true"},{"sourcePath":"payer_info.name","targetPath":"name"}],"profile":"base","version":"R4","rowsPath":"steps.derive_277_claim_status_responses.step_output._claim_status_responses","outputField":"message.fhirPayerOrganizations_277","resourceType":"Organization"},"enabled":true,"required":true,"sequence":702,"step_name":"Build Payer Organization","step_type":"fhir.build","step_alias":"build_payer_organization_fhir_277","description":"Builds the payer (2100A, the information source) as a FHIR Organization resource per claim status response context."},{"config":{"fields":[{"sourcePath":"patient_info.member_id","targetPath":"id"},{"targetPath":"identifier[0].system","literalValue":"http://ezhealthkonnect.local/x12-member-id"},{"sourcePath":"patient_info.member_id","targetPath":"identifier[0].value"},{"sourcePath":"patient_info.last_name","targetPath":"name[0].family"},{"sourcePath":"patient_info.first_name","targetPath":"name[0].given[0]"},{"sourcePath":"patient_info.gender_fhir","targetPath":"gender"}],"profile":"base","version":"R4","rowsPath":"steps.derive_277_claim_status_responses.step_output._claim_status_responses","outputField":"message.fhirPatients_277","resourceType":"Patient"},"enabled":true,"required":true,"sequence":703,"step_name":"Build Patient","step_type":"fhir.build","step_alias":"build_patient_fhir_277","description":"Builds one FHIR Patient resource per context -- the patient is the subscriber when asking about/reporting on herself, or the dependent (2100D/2100E) otherwise."},{"config":{"fields":[{"valueMap":{"prefix":"claim-status-response-"},"transform":"string_prefix","sourcePath":"response_identifier","targetPath":"id"},{"sourcePath":"task_status","targetPath":"status"},{"targetPath":"intent","literalValue":"order"},{"targetPath":"code.coding[0].system","literalValue":"http://terminology.hl7.org/CodeSystem/task-code"},{"targetPath":"code.coding[0].code","literalValue":"fulfill"},{"targetPath":"description","literalValue":"Health Care Claim Status Response (X12 277)"},{"valueMap":{"prefix":"Patient/"},"transform":"string_prefix","sourcePath":"patient_info.member_id","targetPath":"for.reference"},{"targetPath":"owner.identifier.system","literalValue":"http://ezhealthkonnect.local/x12-payer-id"},{"sourcePath":"payer_info.payer_id","targetPath":"owner.identifier.value"},{"targetPath":"businessStatus.coding[0].system","literalValue":"https://x12.org/codes/health-care-claim-status-category-codes"},{"sourcePath":"status_category_code","targetPath":"businessStatus.coding[0].code"},{"targetPath":"identifier[0].system","literalValue":"http://ezhealthkonnect.local/x12-payer-claim-control-number"},{"sourcePath":"payer_claim_control_number","targetPath":"identifier[0].value"}],"profile":"base","version":"R4","rowsPath":"steps.derive_277_claim_status_responses.step_output._claim_status_responses","outputField":"message.fhirTasks_277","resourceType":"Task"},"enabled":true,"required":true,"sequence":704,"step_name":"Build Task","step_type":"fhir.build","step_alias":"build_task_fhir_277","description":"Builds one FHIR Task resource per claim status response, translating the X12 STC category code into FHIR's own Task.status vocabulary -- a code-system translation, never an invented fact: the status always comes straight from the source STC."}]},{"sequence":800,"label":"Branch — 278 (edi-278-to-fhir-sftp)","description":"Auto-routes here only when edi.parse detects transaction set \"278\" — every step below is a no-op (produces zero rows/resources) for any other detected type. Reused verbatim from the standalone \"edi-278-to-fhir-sftp\" template.","steps":[{"config":{"script":"\nvar parsed = (input.message && input.message.parsedEDI) || input.parsedEDI || {};\nvar loops = parsed.loops || {};\n\nif (parsed.transactionSet !== \"278\") {\n  return ({ _prior_auth_contexts: [], _response_contexts: [] });\n}\n\nfunction arr(v) {\n  if (!v) return [];\n  return Array.isArray(v) ? v : [v];\n}\nfunction genderToFHIR(code) {\n  if (code === \"M\") return \"male\";\n  if (code === \"F\") return \"female\";\n  return \"unknown\";\n}\nfunction hcrActionToOutcome(code) {\n  var map = { \"A1\": \"complete\", \"A2\": \"partial\", \"A3\": \"complete\", \"A4\": \"queued\", \"A5\": \"complete\", \"A6\": \"complete\" };\n  return map[code] || \"complete\";\n}\nfunction hcrActionToDisposition(code) {\n  var map = {\n    \"A1\": \"Certified in total\", \"A2\": \"Certified - partial\", \"A3\": \"Not Certified\",\n    \"A4\": \"Pended\", \"A5\": \"Upheld\", \"A6\": \"Modified\"\n  };\n  return map[code] || \"\";\n}\n\nvar umoLevels = arr(loops[\"2000A\"]);\nvar contexts = [];\nvar nowIso = new Date().toISOString();\n\nfor (var umoIdx = 0; umoIdx < umoLevels.length; umoIdx++) {\n  var umoLevel = umoLevels[umoIdx];\n  var umoNM1 = ((umoLevel.loops || {})[\"2010A\"] || {}).NM1 || {};\n  var umoInfo = { umo_id: umoNM1.identificationCode || \"\", name: umoNM1.nameLastOrOrganizationName || \"\" };\n\n  var requesterLevels = arr((umoLevel.loops || {})[\"2000B\"]);\n  for (var reqIdx = 0; reqIdx < requesterLevels.length; reqIdx++) {\n    var reqLevel = requesterLevels[reqIdx];\n    var reqNM1 = (arr((reqLevel.loops || {})[\"2010B\"])[0] || {}).NM1 || {};\n    var providerInfo = { npi: reqNM1.identificationCode || \"\", name: reqNM1.nameLastOrOrganizationName || \"\" };\n\n    var subscriberLevels = arr((reqLevel.loops || {})[\"2000C\"]);\n    for (var subIdx = 0; subIdx < subscriberLevels.length; subIdx++) {\n      var subLevel = subscriberLevels[subIdx];\n      var sub2010C = (subLevel.loops || {})[\"2010C\"] || {};\n      var subNM1 = sub2010C.NM1 || {};\n      var subscriberInfo = {\n        member_id: subNM1.identificationCode || \"\",\n        first_name: subNM1.nameFirst || \"\",\n        last_name: subNM1.nameLastOrOrganizationName || \"\",\n        gender_fhir: \"unknown\",\n      };\n\n      function extractDiagnoses(event) {\n        var out = [];\n        var hi = event.HI || {};\n        var codes = arr(hi.codes);\n        for (var i = 0; i < codes.length; i++) {\n          var c = (codes[i] || {}).code || {};\n          if (c.code) out.push({ system: \"http://hl7.org/fhir/sid/icd-10-cm\", code: c.code });\n        }\n        return out;\n      }\n\n      function extractServiceLines(event) {\n        var out = [];\n        var svcLevels = arr((event.loops || {})[\"2000F\"]);\n        for (var i = 0; i < svcLevels.length; i++) {\n          var svc = svcLevels[i];\n          var sv1 = svc.SV1 || {};\n          var proc = sv1.procedureCode || {};\n          if (!proc.code) continue;\n          out.push({\n            code: proc.code,\n            hcr_action_code: svc.HCR ? svc.HCR.actionCode : \"\",\n          });\n        }\n        return out;\n      }\n\n      function pushContext(patientInfo, event) {\n        var isResponse = !!event.HCR;\n        var hcr = event.HCR || {};\n        contexts.push({\n          patient_info: patientInfo,\n          payer_info: umoInfo,\n          provider_info: providerInfo,\n          created_at: nowIso,\n          request_identifier: event.TRN ? event.TRN.checkOrEFTTraceNumber : \"\",\n          diagnoses: extractDiagnoses(event),\n          service_lines: extractServiceLines(event),\n          is_response: isResponse,\n          hcr_action_code: hcr.actionCode || \"\",\n          hcr_certification_number: hcr.certificationNumber || \"\",\n          claim_outcome: isResponse ? hcrActionToOutcome(hcr.actionCode) : \"\",\n          claim_disposition: isResponse ? hcrActionToDisposition(hcr.actionCode) : \"\",\n        });\n      }\n\n      var dependentLevels = arr((subLevel.loops || {})[\"2000D\"]);\n      for (var depIdx = 0; depIdx < dependentLevels.length; depIdx++) {\n        var depLevel = dependentLevels[depIdx];\n        var dep2010D = (depLevel.loops || {})[\"2010D\"] || {};\n        var depNM1 = dep2010D.NM1 || {};\n        var dependentInfo = {\n          member_id: depNM1.identificationCode || subscriberInfo.member_id,\n          first_name: depNM1.nameFirst || \"\",\n          last_name: depNM1.nameLastOrOrganizationName || \"\",\n          gender_fhir: \"unknown\",\n        };\n        var depEvents = arr(depLevel.loops ? depLevel.loops[\"2000E\"] : []);\n        for (var e = 0; e < depEvents.length; e++) {\n          pushContext(dependentInfo, depEvents[e]);\n        }\n      }\n\n      // The subscriber's OWN patient event is a SIBLING of 2000D within\n      // 2000C's own loops (matching the \"Dependent's real HL parent is the\n      // Subscriber, never the Provider\" rule already learned twice for\n      // 276/277 -- 278's own tree has the SAME shape one level deeper).\n      var subEvents = arr(subLevel.loops ? subLevel.loops[\"2000E\"] : []);\n      for (var se = 0; se < subEvents.length; se++) {\n        pushContext(subscriberInfo, subEvents[se]);\n      }\n    }\n  }\n}\n\n// fhir.build has no whole-resource-row \"condition\" gate (Condition only\n// exists on individual FIELDS/repeatingGroups, never on the top-level\n// config) -- so the ONLY-when-HCR-present ClaimResponse gating must happen\n// HERE, as a pre-filtered second array, the same \"0-or-1-element array so a\n// resource simply isn't built for excluded rows\" convention 271's own\n// insurance/rejection derive script already established.\nvar responseContexts = [];\nfor (var i = 0; i < contexts.length; i++) {\n  if (contexts[i].is_response) responseContexts.push(contexts[i]);\n}\n\nvar _organization_context = [{ _present: true }];\n\nreturn ({ _organization_context: _organization_context, _prior_auth_contexts: contexts, _response_contexts: responseContexts });\n"},"enabled":true,"required":true,"sequence":801,"step_name":"Derive 278 Prior Auth Contexts","step_type":"enrichment.script","step_alias":"derive_278_prior_auth_contexts","description":"Pure structural reshaping only -- this engine transforms X12 <-> FHIR, it never decides a prior authorization outcome. Flattens 278's UMO/requester/subscriber/dependent/patient-event hierarchy into one flat array (_prior_auth_contexts), one row per patient event, computing is_response purely from HCR's own presence (a structural fact already in the message) so the fhir.build steps below can build one Claim (always) and one ClaimResponse (only for a response) per event declaratively via rowsPath/condition."},{"config":{"fields":[{"targetPath":"id","literalValue":"organization-umo"},{"targetPath":"active","literalValue":"true"},{"targetPath":"name","literalValue":"ACME UMO"}],"profile":"base","version":"R4","outputField":"message.fhirOrganization_278","resourceType":"Organization","rowsPath":"steps.derive_278_prior_auth_contexts.step_output._organization_context"},"enabled":true,"required":true,"sequence":802,"step_name":"Build UMO Organization","step_type":"fhir.build","step_alias":"build_umo_organization_fhir_278","description":"Builds the Utilization Management Organization (2010A) as a single FHIR Organization resource."},{"config":{"fields":[{"sourcePath":"patient_info.member_id","targetPath":"id"},{"targetPath":"identifier[0].system","literalValue":"http://ezhealthkonnect.local/x12-member-id"},{"sourcePath":"patient_info.member_id","targetPath":"identifier[0].value"},{"sourcePath":"patient_info.last_name","targetPath":"name[0].family"},{"sourcePath":"patient_info.first_name","targetPath":"name[0].given[0]"},{"sourcePath":"patient_info.gender_fhir","targetPath":"gender"}],"profile":"base","version":"R4","rowsPath":"steps.derive_278_prior_auth_contexts.step_output._prior_auth_contexts","outputField":"message.fhirPatients_278","resourceType":"Patient"},"enabled":true,"required":true,"sequence":803,"step_name":"Build Patient","step_type":"fhir.build","step_alias":"build_patient_fhir_278","description":"Builds one FHIR Patient resource per patient event -- the patient is the subscriber when the event concerns herself, or the dependent (2010D) otherwise."},{"config":{"fields":[{"valueMap":{"prefix":"prior-auth-request-"},"transform":"string_prefix","sourcePath":"request_identifier","targetPath":"id"},{"targetPath":"status","literalValue":"active"},{"targetPath":"type.coding[0].system","literalValue":"http://terminology.hl7.org/CodeSystem/claim-type"},{"targetPath":"type.coding[0].code","literalValue":"professional"},{"targetPath":"use","literalValue":"preauthorization"},{"valueMap":{"prefix":"Patient/"},"transform":"string_prefix","sourcePath":"patient_info.member_id","targetPath":"patient.reference"},{"sourcePath":"created_at","targetPath":"created"},{"targetPath":"provider.identifier.system","literalValue":"http://hl7.org/fhir/sid/us-npi"},{"sourcePath":"provider_info.npi","targetPath":"provider.identifier.value"},{"targetPath":"priority.coding[0].system","literalValue":"http://terminology.hl7.org/CodeSystem/processpriority"},{"targetPath":"priority.coding[0].code","literalValue":"normal"},{"targetPath":"insurance[0].sequence","literalValue":"1"},{"targetPath":"insurance[0].focal","literalValue":"true"},{"targetPath":"insurance[0].coverage.identifier.system","literalValue":"http://ezhealthkonnect.local/x12-umo-id"},{"sourcePath":"payer_info.umo_id","targetPath":"insurance[0].coverage.identifier.value"}],"profile":"base","version":"R4","rowsPath":"steps.derive_278_prior_auth_contexts.step_output._prior_auth_contexts","outputField":"message.fhirClaims_278","resourceType":"Claim","repeatingGroups":[{"fields":[{"transform":"cda_decimal_string_to_number","sourcePath":"_rowIndex","targetPath":"sequence"},{"sourcePath":"system","targetPath":"diagnosisCodeableConcept.coding[0].system"},{"sourcePath":"code","targetPath":"diagnosisCodeableConcept.coding[0].code"}],"rowsPath":"diagnoses","targetPath":"diagnosis"},{"fields":[{"transform":"cda_decimal_string_to_number","sourcePath":"_rowIndex","targetPath":"sequence"},{"targetPath":"productOrService.coding[0].system","literalValue":"http://www.ama-assn.org/go/cpt"},{"sourcePath":"code","targetPath":"productOrService.coding[0].code"}],"rowsPath":"service_lines","targetPath":"item"}]},"enabled":true,"required":true,"sequence":804,"step_name":"Build Claim","step_type":"fhir.build","step_alias":"build_claim_fhir_278","description":"Builds one FHIR Claim resource (use=preauthorization) per patient event -- ALWAYS built, matching Da Vinci PAS's own resource choice for the same real-world business process. diagnosis[] from HI, item[] from each service level's own SV1 procedure code."},{"config":{"fields":[{"valueMap":{"prefix":"prior-auth-response-"},"transform":"string_prefix","sourcePath":"request_identifier","targetPath":"id"},{"targetPath":"status","literalValue":"active"},{"targetPath":"type.coding[0].system","literalValue":"http://terminology.hl7.org/CodeSystem/claim-type"},{"targetPath":"type.coding[0].code","literalValue":"professional"},{"targetPath":"use","literalValue":"preauthorization"},{"valueMap":{"prefix":"Patient/"},"transform":"string_prefix","sourcePath":"patient_info.member_id","targetPath":"patient.reference"},{"sourcePath":"created_at","targetPath":"created"},{"targetPath":"insurer.identifier.system","literalValue":"http://ezhealthkonnect.local/x12-umo-id"},{"sourcePath":"payer_info.umo_id","targetPath":"insurer.identifier.value"},{"sourcePath":"claim_outcome","targetPath":"outcome"},{"sourcePath":"claim_disposition","targetPath":"disposition"},{"sourcePath":"hcr_certification_number","targetPath":"preAuthRef"},{"targetPath":"request.identifier.system","literalValue":"http://ezhealthkonnect.local/x12-prior-auth-trace"},{"sourcePath":"request_identifier","targetPath":"request.identifier.value"}],"profile":"base","version":"R4","rowsPath":"steps.derive_278_prior_auth_contexts.step_output._response_contexts","outputField":"message.fhirClaimResponses_278","resourceType":"ClaimResponse"},"enabled":true,"required":true,"sequence":805,"step_name":"Build ClaimResponse","step_type":"fhir.build","step_alias":"build_claim_response_fhir_278","description":"Builds one FHIR ClaimResponse resource per patient event, but ONLY when HCR (the real certification decision) is present -- a pure request produces zero ClaimResponse rows. HCR01 is translated into FHIR outcome/disposition vocabulary, never invented."}]},{"sequence":900,"label":"Branch — 834 (edi-834-to-fhir-sftp)","description":"Auto-routes here only when edi.parse detects transaction set \"834\" — every step below is a no-op (produces zero rows/resources) for any other detected type. Reused verbatim from the standalone \"edi-834-to-fhir-sftp\" template.","steps":[{"config":{"script":"\nvar parsed = (input.message && input.message.parsedEDI) || input.parsedEDI || {};\nvar loops = parsed.loops || {};\n\nif (parsed.transactionSet !== \"834\") {\n  return ({ _member_coverages: [] });\n}\n\nfunction arr(v) {\n  if (!v) return [];\n  return Array.isArray(v) ? v : [v];\n}\nfunction genderToFHIR(code) {\n  if (code === \"M\") return \"male\";\n  if (code === \"F\") return \"female\";\n  return \"unknown\";\n}\nfunction relationshipToFHIR(code) {\n  var map = { \"18\": \"self\", \"01\": \"spouse\", \"19\": \"child\" };\n  return map[code] || \"other\";\n}\nfunction maintenanceTypeToCoverageStatus(code) {\n  // Real X12 element 875 (Maintenance Type Code) standard values, confirmed\n  // directly against stedi.com/edi/x12-005010/element/875's own code list\n  // AND cross-checked against X12.org's own official 834 examples: \"021\"\n  // Addition and \"025\" Reinstatement both genuinely mean the coverage is\n  // active; \"024\" is \"Cancellation or Termination\" -- the REAL code for a\n  // terminated enrollment (X12.org's own Example 07, \"Terminate Eligibility\n  // for a Subscriber\", uses exactly this code). An earlier version of this\n  // mapping had \"024\"->\"active\" and \"030\"->\"cancelled\" -- backwards: \"030\"\n  // is \"Audit or Compare\" in the real standard, not a termination code at\n  // all. Found and fixed only by testing against real X12.org sample data,\n  // not by re-reading the generic Stedi segment reference a second time.\n  var map = { \"021\": \"active\", \"025\": \"active\", \"024\": \"cancelled\", \"002\": \"cancelled\" };\n  return map[code] || \"active\";\n}\n\nvar members = arr(loops[\"2000\"]);\nvar rows = [];\nvar nowIso = new Date().toISOString();\n\nfor (var i = 0; i < members.length; i++) {\n  var member = members[i];\n  var ins = member.INS || {};\n  var ref = member.REF || {};\n  var m2100A = (member.loops || {})[\"2100A\"] || {};\n  var nm1 = m2100A.NM1 || {};\n  var dmg = m2100A.DMG || {};\n\n  var patientInfo = {\n    member_id: nm1.identificationCode || ref.referenceIdentification || \"\",\n    first_name: nm1.nameFirst || \"\",\n    last_name: nm1.nameLastOrOrganizationName || \"\",\n    dob: dmg.birthDate || \"\",\n    gender_fhir: genderToFHIR(dmg.genderCode),\n    relationship_fhir: relationshipToFHIR(ins.individualRelationshipCode),\n  };\n\n  var coverages = arr((member.loops || {})[\"2300\"]);\n  for (var c = 0; c < coverages.length; c++) {\n    var hd = coverages[c].HD || {};\n    rows.push({\n      patient_info: patientInfo,\n      created_at: nowIso,\n      subscriber_id: ref.referenceIdentification || \"\",\n      plan_description: hd.planCoverageDescription || \"\",\n      insurance_line_code: hd.insuranceLineCode || \"\",\n      coverage_status: maintenanceTypeToCoverageStatus(hd.maintenanceTypeCode || \"\"),\n      maintenance_type_code: hd.maintenanceTypeCode || \"\",\n    });\n  }\n}\n\nvar _organization_context = [{ _present: true }];\n\nreturn ({ _organization_context: _organization_context, _member_coverages: rows });\n"},"enabled":true,"required":true,"sequence":901,"step_name":"Derive 834 Member Coverages","step_type":"enrichment.script","step_alias":"derive_834_member_coverages","description":"Pure structural reshaping only -- this engine transforms X12 <-> FHIR, it never decides enrollment facts. Flattens 834's flat member-list structure (no HL hierarchy) into one row per (member x coverage) pair, translating HD01's own maintenance type code into FHIR's Coverage.status vocabulary along the way (a code-system translation, never an invented fact) so the fhir.build steps below can build one Patient/Coverage per row declaratively via rowsPath."},{"config":{"fields":[{"targetPath":"id","literalValue":"organization-sponsor"},{"targetPath":"active","literalValue":"true"},{"targetPath":"name","literalValue":"ACME CORP"}],"profile":"base","version":"R4","outputField":"message.fhirOrganization_834","resourceType":"Organization","rowsPath":"steps.derive_834_member_coverages.step_output._organization_context"},"enabled":true,"required":true,"sequence":902,"step_name":"Build Sponsor Organization","step_type":"fhir.build","step_alias":"build_sponsor_organization_fhir_834","description":"Builds the plan Sponsor (1000A) as a single FHIR Organization resource."},{"config":{"fields":[{"sourcePath":"patient_info.member_id","targetPath":"id"},{"targetPath":"identifier[0].system","literalValue":"http://ezhealthkonnect.local/x12-member-id"},{"sourcePath":"patient_info.member_id","targetPath":"identifier[0].value"},{"sourcePath":"patient_info.last_name","targetPath":"name[0].family"},{"sourcePath":"patient_info.first_name","targetPath":"name[0].given[0]"},{"transform":"x12_date_to_fhir_date","sourcePath":"patient_info.dob","targetPath":"birthDate"},{"sourcePath":"patient_info.gender_fhir","targetPath":"gender"}],"profile":"base","version":"R4","rowsPath":"steps.derive_834_member_coverages.step_output._member_coverages","outputField":"message.fhirPatients_834","resourceType":"Patient"},"enabled":true,"required":true,"sequence":903,"step_name":"Build Patient","step_type":"fhir.build","step_alias":"build_patient_fhir_834","description":"Builds one FHIR Patient resource per member-coverage row -- a member with N coverages produces N Patient entries sharing the same stable id, harmless per FHIR Bundle semantics (same \"not deduplicated across rows\" precedent 837P/837I already established)."},{"config":{"fields":[{"valueMap":{"prefix":"coverage-"},"transform":"string_prefix","sourcePath":"_rowIndex","targetPath":"id"},{"sourcePath":"coverage_status","targetPath":"status"},{"targetPath":"type.coding[0].system","literalValue":"https://codesystem.x12.org/005010/1205"},{"sourcePath":"insurance_line_code","targetPath":"type.coding[0].code"},{"sourcePath":"subscriber_id","targetPath":"subscriberId"},{"valueMap":{"prefix":"Patient/"},"transform":"string_prefix","sourcePath":"patient_info.member_id","targetPath":"beneficiary.reference"},{"targetPath":"relationship.coding[0].system","literalValue":"http://terminology.hl7.org/CodeSystem/subscriber-relationship"},{"sourcePath":"patient_info.relationship_fhir","targetPath":"relationship.coding[0].code"},{"targetPath":"payor[0].identifier.system","literalValue":"http://ezhealthkonnect.local/x12-payer-id"},{"targetPath":"payor[0].identifier.value","literalValue":"PAYER001"},{"targetPath":"class[0].type.coding[0].system","literalValue":"http://terminology.hl7.org/CodeSystem/coverage-class"},{"targetPath":"class[0].type.coding[0].code","literalValue":"plan"},{"sourcePath":"plan_description","targetPath":"class[0].value"}],"profile":"base","version":"R4","rowsPath":"steps.derive_834_member_coverages.step_output._member_coverages","outputField":"message.fhirCoverages_834","resourceType":"Coverage"},"enabled":true,"required":true,"sequence":904,"step_name":"Build Coverage","step_type":"fhir.build","step_alias":"build_coverage_fhir_834","description":"Builds one FHIR Coverage resource per real-world health-coverage enrollment (834's own 2300 loop), status translated from HD01's own maintenance type code."}]},{"sequence":100,"label":"Branch — 835 (edi-835-to-fhir-sftp)","description":"Auto-routes here only when edi.parse detects transaction set \"835\" — every step below is a no-op (produces zero rows/resources) for any other detected type. Reused verbatim from the standalone \"edi-835-to-fhir-sftp\" template.","steps":[{"config":{"script":"\n// A prior step's plain top-level output field (edi.parse's own \"parsedEDI\",\n// per its outputField config) is NOT exposed to a later step's own \"input\"\n// at the top level -- the real pipeline engine nests it under\n// input.message.parsedEDI instead (confirmed by the 837P/837I derive\n// scripts' own real Test-Pipeline-run finding, which applies here too).\n// Prefer that real shape; fall back to the bare top-level key for\n// Go-level test harnesses that construct { parsedEDI: ... } directly\n// without a \"message\" wrapper (as edi_835_to_fhir_test.go does).\nvar parsed = (input.message && input.message.parsedEDI) || input.parsedEDI || {};\nif (parsed.transactionSet !== \"835\") { return { claim_rows: [], _payment_reconciliation_context: [] }; }\n\nvar loops = parsed.loops || {};\nvar header = parsed.header || {};\n\nfunction arr(v) {\n  if (!v) return [];\n  return Array.isArray(v) ? v : [v];\n}\n\nfunction byEntityIdentifierCode(nm1, code) {\n  var list = arr(nm1);\n  for (var i = 0; i < list.length; i++) {\n    if (list[i].entityIdentifierCode === code) return list[i];\n  }\n  return {};\n}\n\nvar headerPaymentDate = (header.BPR && header.BPR.paymentEffectiveDate) || \"\";\nvar payerName = ((loops[\"1000A\"] || {}).N1 || {}).name || \"\";\n\n// CAS is maxUse \">1\" within a service line (a line can carry more than one\n// CAS occurrence, e.g. one per claim-adjustment-group-code), each with its\n// own up-to-6 reason/amount/quantity trios in its own \"adjustments\" repeat\n// group (edi/schemas/x12_005010/segments/CAS.json). Flatten every\n// occurrence's trios into one combined list here, in JS, rather than\n// relying on fhir.build's own \"CAS[*].adjustments\" wildcard-flatten path —\n// this script now owns all the row reshaping, matching the 837P/837I\n// precedent of doing this flattening once, in one place.\nfunction extractAdjustments(casList) {\n  var instances = arr(casList);\n  var out = [];\n  for (var i = 0; i < instances.length; i++) {\n    var trios = instances[i].adjustments || [];\n    for (var j = 0; j < trios.length; j++) {\n      if (!trios[j].reasonCode) continue;\n      out.push({ reason_code: trios[j].reasonCode, amount: trios[j].amount || \"0\" });\n    }\n  }\n  return out;\n}\n\nfunction extractServiceLines(claimRow) {\n  var lines = arr((claimRow.loops || {})[\"2110\"]);\n  var out = [];\n  for (var i = 0; i < lines.length; i++) {\n    var svc = lines[i].SVC || {};\n    var proc = svc.procedureCode || {};\n    out.push({\n      procedure_code: proc.code || \"\",\n      charge_amount: svc.chargeAmount || \"0\",\n      paid_amount: svc.paidAmount || \"0\",\n      adjustments: extractAdjustments(lines[i].CAS)\n    });\n  }\n  return out;\n}\n\n// 2000 (Header Number) is maxUse \">1\" -- every real sample checked into this\n// repo only ever carries one, but the spec allows more (e.g. a\n// clearinghouse batching multiple LX groups into one interchange), so every\n// group is walked rather than assumed away, mirroring the same\n// walk-every-occurrence fix already made for 837's own 2000A billing\n// provider loop.\nvar claimRows = [];\nvar headerGroups = arr(loops[\"2000\"]);\nfor (var g = 0; g < headerGroups.length; g++) {\n  var claims = arr((headerGroups[g].loops || {})[\"2100\"]);\n  for (var c = 0; c < claims.length; c++) {\n    var claimRow = claims[c];\n    var clp = claimRow.CLP || {};\n    var patientNM1 = byEntityIdentifierCode(claimRow.NM1, \"QC\");\n    // Rendering Provider (role 82) -- named, evidence-based gap: neither\n    // real sample in this repo carries an \"82\" NM1 occurrence at the claim\n    // level, so this resolves empty today, but the mapping itself is\n    // correct per the X12 835 IG and is kept rather than removed.\n    var providerNM1 = byEntityIdentifierCode(claimRow.NM1, \"82\");\n    claimRows.push({\n      patient_control_number: clp.patientControlNumber || \"\",\n      claim_payment_amount: clp.claimPaymentAmount || \"0\",\n      patient_name: patientNM1.nameLastOrOrganizationName || \"\",\n      provider_name: providerNM1.nameLastOrOrganizationName || \"\",\n      header_payment_date: headerPaymentDate,\n      payer_name: payerName,\n      service_lines: extractServiceLines(claimRow)\n    });\n  }\n}\n\nvar _payment_reconciliation_context = [{\n  check_or_eft_trace_number: (header.TRN && header.TRN.checkOrEFTTraceNumber) || \"\",\n  payment_effective_date: headerPaymentDate,\n  total_actual_provider_payment_amount: (header.BPR && header.BPR.totalActualProviderPaymentAmount) || \"\",\n  payer_name: payerName,\n  claim_rows: claimRows\n}];\n\nreturn { _payment_reconciliation_context: _payment_reconciliation_context, claim_rows: claimRows };\n"},"enabled":true,"required":true,"sequence":101,"step_name":"Derive 835 Claim Context","step_type":"enrichment.script","step_alias":"derive_835_claim_context","description":"Pure data reshaping only -- no FHIR resource-shape knowledge. rowsPath's own field resolution is row-only (no automatic fallback to interchange-header data), so this copies the 2 header-level values every claim needs (BPR16 payment date, 1000A payer name) onto EACH claim row, and fully flattens CLP/NM1/SVC/CAS into one flat claim_rows[] array the ExplanationOfBenefit build below can consume declaratively via rowsPath, with no control.loop wrapper step needed."},{"config":{"fields":[{"sourcePath":"patient_control_number","targetPath":"id"},{"targetPath":"status","literalValue":"active"},{"targetPath":"type.coding[0].system","literalValue":"http://terminology.hl7.org/CodeSystem/claim-type"},{"targetPath":"type.coding[0].code","literalValue":"professional"},{"targetPath":"use","literalValue":"claim"},{"targetPath":"outcome","literalValue":"complete"},{"transform":"x12_date_to_fhir_date","sourcePath":"header_payment_date","targetPath":"created"},{"sourcePath":"patient_name","targetPath":"patient.display"},{"sourcePath":"provider_name","targetPath":"provider.display"},{"sourcePath":"payer_name","targetPath":"insurer.display"},{"transform":"cda_decimal_string_to_number","sourcePath":"claim_payment_amount","targetPath":"payment.amount.value"}],"profile":"base","version":"R4","rowsPath":"steps.derive_835_claim_context.step_output.claim_rows","outputField":"message.explanationOfBenefits_835","resourceType":"ExplanationOfBenefit","repeatingGroups":[{"fields":[{"transform":"cda_decimal_string_to_number","sourcePath":"_rowIndex","targetPath":"sequence"},{"targetPath":"productOrService.coding[0].system","literalValue":"https://www.cms.gov/Medicare/Coding/HCPCSReleaseCodeSets"},{"sourcePath":"procedure_code","targetPath":"productOrService.coding[0].code"},{"targetPath":"adjudication[0].category.coding[0].system","literalValue":"http://terminology.hl7.org/CodeSystem/adjudication"},{"targetPath":"adjudication[0].category.coding[0].code","literalValue":"submitted"},{"transform":"cda_decimal_string_to_number","sourcePath":"charge_amount","targetPath":"adjudication[0].amount.value"},{"targetPath":"adjudication[1].category.coding[0].system","literalValue":"http://terminology.hl7.org/CodeSystem/adjudication"},{"targetPath":"adjudication[1].category.coding[0].code","literalValue":"benefit"},{"transform":"cda_decimal_string_to_number","sourcePath":"paid_amount","targetPath":"adjudication[1].amount.value"}],"rowsPath":"service_lines","targetPath":"item","repeatingGroups":[{"fields":[{"targetPath":"category.coding[0].system","literalValue":"https://x12.org/codes/claim-adjustment-reason-codes"},{"sourcePath":"reason_code","targetPath":"category.coding[0].code"},{"transform":"cda_decimal_string_to_number","sourcePath":"amount","targetPath":"amount.value"}],"rowsPath":"adjustments","targetPath":"adjudication"}]}]},"enabled":true,"required":true,"sequence":102,"step_name":"Build ExplanationOfBenefit","step_type":"fhir.build","step_alias":"build_eob_fhir_835","description":"Builds one FHIR ExplanationOfBenefit resource PER CLAIM (rowsPath mode) from the derive step above. item.sequence uses the new $rowIndex-style \"_rowIndex\" primitive (fhir_build_executor.go) every row carries automatically. Real, named gaps left unmapped: EOB.type is hardcoded \"professional\" (an 835 alone can't reliably distinguish claim types); EOB.provider (no role-82 NM1 in real 835 samples) and EOB.insurance (no Coverage resource built in this pass) are left unpopulated -- strict validation will report exactly these 2 required-field gaps, nothing else."},{"config":{"fields":[{"sourcePath":"check_or_eft_trace_number","targetPath":"id"},{"targetPath":"status","literalValue":"active"},{"targetPath":"outcome","literalValue":"complete"},{"transform":"x12_date_to_fhir_date","sourcePath":"payment_effective_date","targetPath":"created"},{"transform":"x12_date_to_fhir_date","sourcePath":"payment_effective_date","targetPath":"paymentDate"},{"transform":"cda_decimal_string_to_number","sourcePath":"total_actual_provider_payment_amount","targetPath":"paymentAmount.value"},{"sourcePath":"payer_name","targetPath":"paymentIssuer.display"}],"profile":"base","version":"R4","outputField":"message.paymentReconciliation_835","resourceType":"PaymentReconciliation","repeatingGroups":[{"fields":[{"transform":"cda_decimal_string_to_number","sourcePath":"claim_payment_amount","targetPath":"amount.value"},{"valueMap":{"prefix":"ExplanationOfBenefit/"},"transform":"string_prefix","sourcePath":"patient_control_number","targetPath":"response.reference"}],"rowsPath":"claim_rows","targetPath":"detail"}],"rowsPath":"steps.derive_835_claim_context.step_output._payment_reconciliation_context"},"enabled":true,"required":true,"sequence":103,"step_name":"Build PaymentReconciliation","step_type":"fhir.build","step_alias":"build_payment_reconciliation_835","description":"Builds one PaymentReconciliation resource from the interchange's BPR (payment amount/date) and TRN (check/EFT trace number) header segments, plus the payer's own N1 identity from loop 1000A. detail[].response.reference is keyed off the same CLP.patientControlNumber value the ExplanationOfBenefit build above uses for its own id, so payload.builder's fullUrl-rewrite correctly cross-references each EOB. Unchanged from this template's prior version (V231/V234) -- reads parsedEDI directly, never through a script's own step_output, so none of the row-scoping/snake-casing rules governing the EOB step above apply here."}]},{"sequence":300,"label":"Branch — 837I (edi-837i-to-fhir-sftp)","description":"Auto-routes here only when edi.parse detects transaction set \"837I\" — every step below is a no-op (produces zero rows/resources) for any other detected type. Reused verbatim from the standalone \"edi-837i-to-fhir-sftp\" template.","steps":[{"config":{"script":"\n// -- Derive 837I Claim Contexts --\n// See edi_837p_fhir_builder_test.go's own derive script comment for the full\n// \"message.\" nesting rationale -- same fix applies here.\nvar parsed = (input.message && input.message.parsedEDI) || input.parsedEDI || {};\nvar loops = parsed.loops || {};\n\nif (parsed.transactionSet !== \"837I\") {\n  return ({ _claim_contexts: [], _coverage_contexts: [], _billing_providers: [] });\n}\n\nfunction arr(v) {\n  if (!v) return [];\n  return Array.isArray(v) ? v : [v];\n}\nfunction first(v) {\n  var a = arr(v);\n  return a.length > 0 ? a[0] : {};\n}\n\nfunction genderToFHIR(code) {\n  if (code === \"M\") return \"male\";\n  if (code === \"F\") return \"female\";\n  return \"unknown\";\n}\n\nfunction relationshipToFHIR(code) {\n  var map = { \"18\": \"self\", \"01\": \"spouse\", \"19\": \"child\", \"20\": \"employee\" };\n  return map[code] || \"other\";\n}\n\n// See edi_837p_fhir_builder_test.go's own derive script comment for why every\n// 2000A is walked instead of just the first, and for the billingProviderId\n// scheme.\nfunction billingProviderId(npi, idx) {\n  return \"organization-billing-\" + (npi || String(idx + 1));\n}\nvar billingProviderLevels = arr(loops[\"2000A\"]);\nvar billingProviders = [];\nfor (var bpIdx = 0; bpIdx < billingProviderLevels.length; bpIdx++) {\n  var bpProviderLoop = (billingProviderLevels[bpIdx].loops || {})[\"2010AA\"] || {};\n  var bpNM1 = first(bpProviderLoop.NM1);\n  var bpNpi = bpNM1.identificationCode || \"\";\n  billingProviders.push({\n    id: billingProviderId(bpNpi, bpIdx),\n    npi: bpNpi,\n    name: bpNM1.nameLastOrOrganizationName || \"\"\n  });\n}\n\n// HI is SHARED for diagnosis and procedure codes on 837I, distinguished\n// purely by each repetition's own qualifier. Diagnosis qualifiers come in\n// ICD-9/ICD-10 pairs (BK/ABK = principal, BF/ABF = other, BJ/ABJ =\n// admitting, BN/ABN = external cause of injury, PR/APR = patient's reason\n// for visit) -- an X12.org real-world sample (the \"Jones Hospital\" 005010X223\n// example, ICD-9-CM era) caught a real gap here: an earlier version of\n// extractDiagnoses only matched the \"AB\"-prefixed ICD-10 forms, silently\n// dropping every ICD-9 diagnosis (BK/BF/etc). Procedure qualifiers are\n// BR/BBR (principal) and BQ/BBQ (other). Value/occurrence/condition codes\n// (BE/BH/BG) and DRG (DR) are not modeled in this pass (named\n// simplification, matching 835's own \"core fields, not exhaustive\"\n// precedent) -- excluded automatically since they're not in either\n// whitelist below.\nvar DIAGNOSIS_HI_QUALIFIERS = [\"BK\", \"ABK\", \"BF\", \"ABF\", \"BJ\", \"ABJ\", \"BN\", \"ABN\", \"PR\", \"APR\"];\nvar PROCEDURE_HI_QUALIFIERS = [\"BR\", \"BBR\", \"BQ\", \"BBQ\"];\n// HI is maxUse \">1\" -- a claim can carry SEVERAL separate HI segment\n// occurrences at the same 2300 level (one per qualifier-group; see\n// edi/schemas/x12_005010/segments/HI.json's own maxUse-correction note for\n// why, found via testing against real, unedited samples), each with its own\n// up-to-12-entry codes[] repeat group. Flatten every occurrence's codes[]\n// into one combined list before filtering by qualifier.\nfunction allHICodes(hiList) {\n  var instances = arr(hiList);\n  var out = [];\n  for (var i = 0; i < instances.length; i++) {\n    var codes = (instances[i] && instances[i].codes) || [];\n    for (var j = 0; j < codes.length; j++) out.push(codes[j]);\n  }\n  return out;\n}\n\nfunction extractDiagnoses(codes) {\n  var out = [];\n  for (var i = 0; i < codes.length; i++) {\n    var c = (codes[i] && codes[i].code) || {};\n    if (!c.code) continue;\n    var q = c.qualifier || \"\";\n    if (DIAGNOSIS_HI_QUALIFIERS.indexOf(q) === -1) continue;\n    var entry = { code: c.code, sequence: out.length + 1 };\n    // Omit the key entirely (not an empty string) when absent -- an empty\n    // onAdmission.coding[0].code sourcePath still resolves as \"not empty\n    // data\" for a LITERAL system field with no sourcePath of its own, so the\n    // Claim config's own condition (checking this field \"exists\") only works\n    // correctly when the key is truly missing from the row, not blank.\n    if (c.presentOnAdmissionIndicator) { entry.on_admission = c.presentOnAdmissionIndicator; }\n    out.push(entry);\n  }\n  return out;\n}\n\nfunction extractProcedures(codes) {\n  var out = [];\n  for (var i = 0; i < codes.length; i++) {\n    var c = (codes[i] && codes[i].code) || {};\n    if (!c.code) continue;\n    var q = c.qualifier || \"\";\n    if (PROCEDURE_HI_QUALIFIERS.indexOf(q) === -1) continue;\n    out.push({ code: c.code, sequence: out.length + 1 });\n  }\n  return out;\n}\n\nfunction extractInstitutionalInfo(cl1) {\n  var out = [];\n  var seq = 0;\n  if (!cl1) return out;\n  if (cl1.admissionTypeCode) { seq++; out.push({ category: \"admissiontype\", code: cl1.admissionTypeCode, sequence: seq }); }\n  if (cl1.admissionSourceCode) { seq++; out.push({ category: \"admissionsource\", code: cl1.admissionSourceCode, sequence: seq }); }\n  if (cl1.patientStatusCode) { seq++; out.push({ category: \"patientstatus\", code: cl1.patientStatusCode, sequence: seq }); }\n  return out;\n}\n\nfunction extractServiceLines(claimLoops) {\n  var lines = arr((claimLoops || {})[\"2400\"]);\n  var out = [];\n  for (var i = 0; i < lines.length; i++) {\n    var line = lines[i];\n    var lx = line.LX || {};\n    var sv2 = line.SV2 || {};\n    var proc = sv2.procedureCode || {};\n    var dtpList = arr(line.DTP);\n    var svc = resolveServicedDate(dtpList);\n    var entry = {\n      sequence: parseInt(lx.assignedNumber || String(i + 1), 10),\n      revenue_code: sv2.serviceLineRevenueCode || \"\",\n      quantity: sv2.serviceUnitCount ? Number(sv2.serviceUnitCount) : 1,\n      net: sv2.lineItemChargeAmount ? Number(sv2.lineItemChargeAmount) : 0,\n      serviced_date: svc.servicedDate,\n      serviced_start: svc.servicedStart,\n      serviced_end: svc.servicedEnd\n    };\n    // Claim.item.productOrService is ALWAYS anchored on the revenue code\n    // (Claim config's own productOrService.coding[0], built directly off\n    // revenueCode) -- the one identifier EVERY real institutional line\n    // carries, and the field an official X12.org example (005010X223A2\n    // Example 1a) shows populated on every line even when a procedure code\n    // is ALSO present. SV202 (procedure code) is genuinely OPTIONAL on real\n    // institutional claims -- present on many ancillary/outpatient lines\n    // (often required under CMS OPPS rules for specific revenue codes),\n    // absent on others (room & board, some inpatient DRG-based lines; a\n    // real, unedited sample checked this round had NO procedure code on any\n    // of its 9 lines). When present, it's added as a SECOND coding in the\n    // SAME productOrService CodeableConcept (Claim config's own\n    // productOrService.coding[1]) -- never a replacement for the revenue-\n    // code coding. Keys omitted entirely (not set to \"\") when absent,\n    // matching the same \"a condition checking a field 'exists' must see a\n    // truly missing key, not an empty string\" convention onAdmission\n    // already established.\n    if (proc.code) {\n      entry.procedure_code = proc.code;\n      entry.procedure_system = (proc.qualifier === \"HC\") ? \"http://www.ama-assn.org/go/cpt\" : \"\";\n    }\n    out.push(entry);\n  }\n  return out;\n}\n\n// DTP02 (Date/Time Period Format Qualifier) \"D8\" is a single CCYYMMDD date;\n// \"RD8\" is a CCYYMMDD-CCYYMMDD range. Claim.item.serviced[x] is a choice type\n// (servicedDate | servicedPeriod) -- only one of the two shapes below is ever\n// populated per DTP*472 occurrence, matching that choice. Found only by\n// testing against a real, unedited 837 sample (databricks-industry-\n// solutions/x12-edi-parser's own CC_837P_EDI.txt/CC_837I_EDI.txt test\n// fixtures) carrying genuine RD8 ranges -- the synthetic Go-test fixture\n// only ever used D8 dates, so this gap was invisible there.\nfunction resolveServicedDate(dtpList) {\n  for (var d = 0; d < dtpList.length; d++) {\n    if (dtpList[d].dateTimeQualifier !== \"472\") continue;\n    var period = dtpList[d].datePeriod || \"\";\n    if (dtpList[d].dateTimePeriodFormatQualifier === \"RD8\" && period.indexOf(\"-\") !== -1) {\n      var parts = period.split(\"-\");\n      return { servicedDate: \"\", servicedStart: parts[0] || \"\", servicedEnd: parts[1] || \"\" };\n    }\n    return { servicedDate: period, servicedStart: \"\", servicedEnd: \"\" };\n  }\n  return { servicedDate: \"\", servicedStart: \"\", servicedEnd: \"\" };\n}\n\n// Institutional care-team roles are genuinely different assignments from\n// professional's own 2310A/2310B (Referring/Rendering) -- 2310A=Attending,\n// 2310B=Operating Physician, 2310D=Rendering, 2310F=Referring.\n// Provider identification prefers NM1's own NPI (identificationCodeQualifier\n// \"XX\"), but real, spec-compliant claims sometimes carry NO NM1 identifier at\n// all for a pre-NPI-era provider, identifying them via a SEPARATE REF segment\n// instead (e.g. REF*1G = Provider UPIN Number) -- confirmed directly against\n// X12.org's own official \"Jones Hospital\" 837I example, whose attending\n// physician (NM1*71*1*JONES*JOHN*J, no NM108/09 at all) is followed by\n// REF*1G*B99937. Previously this NM1-only check silently produced an EMPTY\n// care team for exactly this real, non-fabricated case. The REF qualifier\n// itself (1G/0B/G2/...) is carried through as part of the identifier system\n// URI rather than assumed to always be UPIN, since any of several secondary\n// qualifiers are possible here per the base X12 REF01 code list.\nfunction providerIdentifier(entity) {\n  if (entity.identificationCode) {\n    return { identifier_system: \"http://hl7.org/fhir/sid/us-npi\", identifier_value: entity.identificationCode };\n  }\n  var ref = first(entity.REF);\n  if (ref.referenceIdentification) {\n    return {\n      identifier_system: \"http://ezhealthkonnect.local/x12-ref-qualifier/\" + (ref.referenceIdentificationQualifier || \"unknown\"),\n      identifier_value: ref.referenceIdentification\n    };\n  }\n  return null;\n}\n\nfunction extractCareTeam(claimLoops) {\n  var team = [];\n  var roleLoops = [\n    { key: \"2310A\", role: \"attending\" },\n    { key: \"2310B\", role: \"operating\" },\n    { key: \"2310D\", role: \"rendering\" },\n    { key: \"2310F\", role: \"referring\" }\n  ];\n  for (var r = 0; r < roleLoops.length; r++) {\n    var loop = (claimLoops || {})[roleLoops[r].key];\n    if (!loop) continue;\n    var nm1 = first(loop.NM1);\n    var ident = providerIdentifier({ identificationCode: nm1.identificationCode, REF: loop.REF });\n    if (ident) {\n      team.push({ identifier_system: ident.identifier_system, identifier_value: ident.identifier_value, role: roleLoops[r].role, sequence: team.length + 1 });\n    }\n  }\n  return team;\n}\n\n// Claim.facility (base FHIR, 0..1 Reference) -- 2310E Service Facility\n// Location on 837I (a genuinely different loop position from 837P's own\n// 2310C, since institutional's role numbering differs -- see this file's own\n// header comment). Same logical (identifier-only) reference pattern as\n// careTeam[].provider; not a care-team member. See\n// edi_837p_fhir_builder_test.go's own extractFacility for the full rationale\n// (found via X12.org's official COB example on the professional side).\nfunction extractFacility(claimLoops) {\n  var loop = (claimLoops || {})[\"2310E\"];\n  if (!loop) return {};\n  var nm1 = first(loop.NM1);\n  if (!nm1.identificationCode) return {};\n  return { facility_npi: nm1.identificationCode, facility_name: nm1.nameLastOrOrganizationName || \"\" };\n}\n\n// See edi_837p_fhir_builder_test.go's own extractOtherPayers/\n// buildInsuranceAndCoverage for the full COB rationale -- 2320/2330B is\n// identical shape across 837P/837I.\nfunction extractOtherPayers(claimLoops) {\n  var out = [];\n  var list = arr((claimLoops || {})[\"2320\"]);\n  for (var i = 0; i < list.length; i++) {\n    var payerNM1 = first(((list[i].loops || {})[\"2330B\"] || {}).NM1);\n    if (!payerNM1.identificationCode) continue;\n    out.push({ payer_id: payerNM1.identificationCode, payer_name: payerNM1.nameLastOrOrganizationName || \"\" });\n  }\n  return out;\n}\n\nfunction buildInsuranceAndCoverage(payerInfo, patientInfo, subscriberInfo, claimLoops, pcn) {\n  var baseId = \"coverage-\" + pcn;\n  var insuranceList = [{ sequence: 1, focal: true, coverage_id: baseId }];\n  var coverageRows = [{\n    patient_info: patientInfo, subscriber_info: subscriberInfo, payer_info: payerInfo,\n    coverage_id: baseId, sequence: 1, focal: true\n  }];\n  var others = extractOtherPayers(claimLoops);\n  for (var i = 0; i < others.length; i++) {\n    var seq = i + 2;\n    var cid = baseId + \"-\" + seq;\n    insuranceList.push({ sequence: seq, focal: false, coverage_id: cid });\n    coverageRows.push({\n      patient_info: patientInfo, subscriber_info: subscriberInfo,\n      payer_info: { name: others[i].payer_name, payer_id: others[i].payer_id },\n      coverage_id: cid, sequence: seq, focal: false\n    });\n  }\n  return { insurance_list: insuranceList, coverage_rows: coverageRows };\n}\n\nvar nowISO = new Date().toISOString();\n\n// See edi_837p_fhir_builder_test.go's own buildClaimContext doc comment for\n// why every returned property name here is snake_case, not camelCase.\nfunction buildClaimContext(patientInfo, subscriberInfo, payerInfo, claimLoop, billingProviderId) {\n  var clm = claimLoop.CLM || {};\n  var svcLoc = clm.healthCareServiceLocation || {};\n  var facility = extractFacility(claimLoop.loops);\n  var pcn = clm.patientControlNumber || \"\";\n  var insCov = buildInsuranceAndCoverage(payerInfo, patientInfo, subscriberInfo, claimLoop.loops, pcn);\n  var claim = {\n    patient_control_number: pcn,\n    total_charge_amount: clm.totalClaimChargeAmount ? Number(clm.totalClaimChargeAmount) : 0,\n    place_of_service_code: svcLoc.placeOfServiceCode || \"\",\n    created_at: nowISO,\n    billing_provider_id: billingProviderId,\n    diagnosis_list: extractDiagnoses(allHICodes(claimLoop.HI)),\n    procedure_list: extractProcedures(allHICodes(claimLoop.HI)),\n    institutional_info: extractInstitutionalInfo(claimLoop.CL1),\n    service_lines: extractServiceLines(claimLoop.loops),\n    care_team: extractCareTeam(claimLoop.loops),\n    insurance_list: insCov.insurance_list\n  };\n  if (facility.facility_npi) {\n    claim.facility_npi = facility.facility_npi;\n    claim.facility_name = facility.facility_name;\n  }\n  return {\n    context: {\n      patient_info: patientInfo,\n      subscriber_info: subscriberInfo,\n      payer_info: payerInfo,\n      claim: claim\n    },\n    coverage_rows: insCov.coverage_rows\n  };\n}\n\nfunction personFromNM1AndDMG(nm1, dmg, relationshipCode) {\n  var gender = dmg.genderCode || \"\";\n  return {\n    first_name: nm1.nameFirst || \"\",\n    last_name: nm1.nameLastOrOrganizationName || \"\",\n    member_id: nm1.identificationCode || \"\",\n    dob: dmg.birthDate || \"\",\n    gender_fhir: genderToFHIR(gender),\n    relationship_code: relationshipCode || \"\",\n    relationship_fhir: relationshipToFHIR(relationshipCode || \"\")\n  };\n}\n\nvar claimContexts = [];\nvar coverageContexts = [];\n\nfunction pushClaimContext(built) {\n  claimContexts.push(built.context);\n  for (var cr = 0; cr < built.coverage_rows.length; cr++) coverageContexts.push(built.coverage_rows[cr]);\n}\n\nfor (var bp = 0; bp < billingProviderLevels.length; bp++) {\n  var bpId = billingProviders[bp].id;\n  var billingLoops = billingProviderLevels[bp].loops || {};\n  var subscriberLevels = arr(billingLoops[\"2000B\"]);\n  for (var s = 0; s < subscriberLevels.length; s++) {\n    var subLevel = subscriberLevels[s];\n    var subLoops = subLevel.loops || {};\n    var sbr = subLevel.SBR || {};\n\n    var subNM1 = first((subLoops[\"2010BA\"] || {}).NM1);\n    var subDMG = (subLoops[\"2010BA\"] || {}).DMG || {};\n    var subscriberInfo = personFromNM1AndDMG(subNM1, subDMG, \"18\");\n\n    var payerNM1 = first((subLoops[\"2010BB\"] || {}).NM1);\n    var payerInfo = {\n      name: payerNM1.nameLastOrOrganizationName || \"\",\n      payer_id: payerNM1.identificationCode || \"\"\n    };\n\n    var dependentLevels = arr(subLoops[\"2000C\"]);\n    if (dependentLevels.length > 0) {\n      for (var d = 0; d < dependentLevels.length; d++) {\n        var depLevel = dependentLevels[d];\n        var depLoops = depLevel.loops || {};\n        var depNM1 = first((depLoops[\"2010CA\"] || {}).NM1);\n        var depDMG = (depLoops[\"2010CA\"] || {}).DMG || {};\n        var depPAT = depLevel.PAT || {};\n        // See edi_837p_fhir_builder_test.go's own dependent-relationship comment\n        // -- same real-world PAT01-vs-SBR02 correction applies here (the 2000C\n        // loop and PAT segment are identical shape across 837P/837I).\n        var patientInfo = personFromNM1AndDMG(depNM1, depDMG, depPAT.individualRelationshipCode || sbr.individualRelationshipCode);\n        if (!patientInfo.member_id) patientInfo.member_id = subscriberInfo.member_id + \"-DEP\" + (d + 1);\n\n        var depClaims = arr(depLoops[\"2300\"]);\n        for (var dc = 0; dc < depClaims.length; dc++) {\n          pushClaimContext(buildClaimContext(patientInfo, subscriberInfo, payerInfo, depClaims[dc], bpId));\n        }\n      }\n    } else {\n      var subClaims = arr(subLoops[\"2300\"]);\n      for (var sc = 0; sc < subClaims.length; sc++) {\n        pushClaimContext(buildClaimContext(subscriberInfo, subscriberInfo, payerInfo, subClaims[sc], bpId));\n      }\n    }\n  }\n}\n\nreturn ({\n  _claim_contexts: claimContexts,\n  _coverage_contexts: coverageContexts,\n  _billing_providers: billingProviders\n});\n"},"enabled":true,"required":true,"sequence":301,"step_name":"Derive 837I Claim Contexts","step_type":"enrichment.script","step_alias":"derive_837i_claim_contexts","description":"Pure data reshaping only -- no FHIR resource-shape or profile knowledge. Flattens 837I's nested billing-provider/subscriber/dependent/claim/service-line/diagnosis/procedure structure into one flat array (_claim_contexts), splitting HI's shared diagnosis/procedure qualifiers, so the fhir.build steps below can build one Patient/Coverage/Claim resource per claim declaratively via rowsPath."},{"config":{"fields":[{"sourcePath":"id","targetPath":"id"},{"targetPath":"active","literalValue":"true"},{"targetPath":"identifier[0].system","literalValue":"http://hl7.org/fhir/sid/us-npi"},{"sourcePath":"npi","targetPath":"identifier[0].value"},{"sourcePath":"name","targetPath":"name"}],"profile":"base","version":"R4","rowsPath":"steps.derive_837i_claim_contexts.step_output._billing_providers","outputField":"message.fhirOrganizations_837i","resourceType":"Organization"},"enabled":true,"required":true,"sequence":302,"step_name":"Build Organization","step_type":"fhir.build","step_alias":"build_organization_fhir_837i","description":"Builds one FHIR Organization resource per distinct 2000A billing provider found in the file (rowsPath mode) -- id is NPI-anchored (organization-billing-<npi>), referenced by each claim's own Claim.provider via its billing_provider_id."},{"config":{"fields":[{"sourcePath":"patient_info.member_id","targetPath":"id"},{"targetPath":"identifier[0].system","literalValue":"http://ezhealthkonnect.local/x12-member-id"},{"sourcePath":"patient_info.member_id","targetPath":"identifier[0].value"},{"sourcePath":"patient_info.last_name","targetPath":"name[0].family"},{"sourcePath":"patient_info.first_name","targetPath":"name[0].given[0]"},{"transform":"x12_date_to_fhir_date","sourcePath":"patient_info.dob","targetPath":"birthDate"},{"sourcePath":"patient_info.gender_fhir","targetPath":"gender"}],"profile":"base","version":"R4","rowsPath":"steps.derive_837i_claim_contexts.step_output._claim_contexts","outputField":"message.fhirPatients_837i","resourceType":"Patient"},"enabled":true,"required":true,"sequence":303,"step_name":"Build Patient","step_type":"fhir.build","step_alias":"build_patient_fhir_837i","description":"Builds one FHIR Patient resource per claim context (rowsPath mode) -- the patient is the subscriber when they are their own patient, or the dependent (2010CA) otherwise. Identical shape to V237's own Patient step."},{"config":{"fields":[{"sourcePath":"coverage_id","targetPath":"id"},{"targetPath":"status","literalValue":"active"},{"valueMap":{"prefix":"Patient/"},"transform":"string_prefix","sourcePath":"patient_info.member_id","targetPath":"beneficiary.reference"},{"sourcePath":"subscriber_info.member_id","targetPath":"subscriberId"},{"valueMap":{"prefix":"Patient/"},"condition":{"field":"patient_info.relationship_code","value":"18","operator":"equals"},"transform":"string_prefix","sourcePath":"subscriber_info.member_id","targetPath":"subscriber.reference"},{"targetPath":"relationship.coding[0].system","literalValue":"http://terminology.hl7.org/CodeSystem/subscriber-relationship"},{"sourcePath":"patient_info.relationship_fhir","targetPath":"relationship.coding[0].code"},{"targetPath":"payor[0].identifier.system","literalValue":"http://ezhealthkonnect.local/x12-payer-id"},{"sourcePath":"payer_info.payer_id","targetPath":"payor[0].identifier.value"},{"sourcePath":"payer_info.name","targetPath":"payor[0].display"}],"profile":"base","version":"R4","rowsPath":"steps.derive_837i_claim_contexts.step_output._coverage_contexts","outputField":"message.fhirCoverages_837i","resourceType":"Coverage"},"enabled":true,"required":true,"sequence":304,"step_name":"Build Coverage","step_type":"fhir.build","step_alias":"build_coverage_fhir_837i","description":"Builds one FHIR Coverage resource per claim x payer pair (rowsPath mode) -- a claim with a COB secondary payer gets its own second Coverage. coverage_id is pre-computed per row by the derive script. Identical shape to V239's own Coverage step -- subscriber.reference only written when the patient IS the subscriber, avoiding a dangling reference in the dependent case."},{"config":{"fields":[{"valueMap":{"prefix":"claim-"},"transform":"string_prefix","sourcePath":"claim.patient_control_number","targetPath":"id"},{"targetPath":"identifier[0].system","literalValue":"http://ezhealthkonnect.local/x12-claim-control-number"},{"sourcePath":"claim.patient_control_number","targetPath":"identifier[0].value"},{"targetPath":"status","literalValue":"active"},{"targetPath":"type.coding[0].system","literalValue":"http://terminology.hl7.org/CodeSystem/claim-type"},{"targetPath":"type.coding[0].code","literalValue":"institutional"},{"targetPath":"use","literalValue":"claim"},{"sourcePath":"claim.created_at","targetPath":"created"},{"targetPath":"priority.coding[0].system","literalValue":"http://terminology.hl7.org/CodeSystem/processpriority"},{"targetPath":"priority.coding[0].code","literalValue":"normal"},{"valueMap":{"prefix":"Patient/"},"transform":"string_prefix","sourcePath":"patient_info.member_id","targetPath":"patient.reference"},{"valueMap":{"prefix":"Organization/"},"transform":"string_prefix","sourcePath":"claim.billing_provider_id","targetPath":"provider.reference"},{"targetPath":"insurer.identifier.system","literalValue":"http://ezhealthkonnect.local/x12-payer-id"},{"sourcePath":"payer_info.payer_id","targetPath":"insurer.identifier.value"},{"condition":{"field":"claim.facility_npi","operator":"exists"},"targetPath":"facility.identifier.system","literalValue":"http://hl7.org/fhir/sid/us-npi"},{"sourcePath":"claim.facility_npi","targetPath":"facility.identifier.value"},{"sourcePath":"claim.total_charge_amount","targetPath":"total.value"},{"targetPath":"total.currency","literalValue":"USD"}],"profile":"base","version":"R4","rowsPath":"steps.derive_837i_claim_contexts.step_output._claim_contexts","outputField":"message.fhirClaims_837i","resourceType":"Claim","repeatingGroups":[{"fields":[{"targetPath":"diagnosisCodeableConcept.coding[0].system","literalValue":"http://hl7.org/fhir/sid/icd-10-cm"},{"sourcePath":"code","targetPath":"diagnosisCodeableConcept.coding[0].code"},{"sourcePath":"sequence","targetPath":"sequence"},{"condition":{"field":"on_admission","operator":"exists"},"targetPath":"onAdmission.coding[0].system","literalValue":"https://codesystem.x12.org/005010/1352"},{"sourcePath":"on_admission","targetPath":"onAdmission.coding[0].code"}],"rowsPath":"claim.diagnosis_list","targetPath":"diagnosis"},{"fields":[{"targetPath":"procedureCodeableConcept.coding[0].system","literalValue":"http://www.cms.gov/Medicare/Coding/ICD10"},{"sourcePath":"code","targetPath":"procedureCodeableConcept.coding[0].code"},{"sourcePath":"sequence","targetPath":"sequence"}],"rowsPath":"claim.procedure_list","targetPath":"procedure"},{"fields":[{"sourcePath":"sequence","targetPath":"sequence"},{"sourcePath":"category","targetPath":"category.coding[0].code"},{"sourcePath":"code","targetPath":"code.coding[0].code"}],"rowsPath":"claim.institutional_info","targetPath":"supportingInfo"},{"fields":[{"sourcePath":"sequence","targetPath":"sequence"},{"targetPath":"revenue.coding[0].system","literalValue":"https://codesystem.x12.org/005010/234"},{"sourcePath":"revenue_code","targetPath":"revenue.coding[0].code"},{"targetPath":"productOrService.coding[0].system","literalValue":"https://codesystem.x12.org/005010/234"},{"sourcePath":"revenue_code","targetPath":"productOrService.coding[0].code"},{"sourcePath":"procedure_system","targetPath":"productOrService.coding[1].system"},{"sourcePath":"procedure_code","targetPath":"productOrService.coding[1].code"},{"sourcePath":"quantity","targetPath":"quantity.value"},{"sourcePath":"net","targetPath":"net.value"},{"targetPath":"net.currency","literalValue":"USD"},{"transform":"x12_date_to_fhir_date","sourcePath":"serviced_date","targetPath":"servicedDate"},{"transform":"x12_date_to_fhir_date","sourcePath":"serviced_start","targetPath":"servicedPeriod.start"},{"transform":"x12_date_to_fhir_date","sourcePath":"serviced_end","targetPath":"servicedPeriod.end"}],"rowsPath":"claim.service_lines","targetPath":"item"},{"fields":[{"sourcePath":"sequence","targetPath":"sequence"},{"sourcePath":"role","targetPath":"role.coding[0].code"},{"sourcePath":"identifier_system","targetPath":"provider.identifier.system"},{"sourcePath":"identifier_value","targetPath":"provider.identifier.value"}],"rowsPath":"claim.care_team","targetPath":"careTeam"},{"fields":[{"sourcePath":"sequence","targetPath":"sequence"},{"sourcePath":"focal","targetPath":"focal"},{"valueMap":{"prefix":"Coverage/"},"transform":"string_prefix","sourcePath":"coverage_id","targetPath":"coverage.reference"}],"rowsPath":"claim.insurance_list","targetPath":"insurance"}]},"enabled":true,"required":true,"sequence":305,"step_name":"Build Claim","step_type":"fhir.build","step_alias":"build_claim_fhir_837i","description":"Builds one FHIR Claim resource per claim context (rowsPath mode). diagnosis[]/procedure[]/supportingInfo[]/item[]/careTeam[] built via repeatingGroups off the context's own pre-flattened arrays. onAdmission fields are conditional on the row actually carrying one. careTeam[].provider is a logical (identifier-only) reference. priority is fixed (no X12 837 equivalent)."}]},{"sequence":200,"label":"Branch — 837P (edi-837p-to-fhir-sftp)","description":"Auto-routes here only when edi.parse detects transaction set \"837P\" — every step below is a no-op (produces zero rows/resources) for any other detected type. Reused verbatim from the standalone \"edi-837p-to-fhir-sftp\" template.","steps":[{"config":{"script":"\n// -- Derive 837P Claim Contexts --\n// A prior step's plain top-level output field (edi.parse's own \"parsedEDI\",\n// per its outputField config) is NOT exposed to a later step's own \"input\"\n// at the top level -- the real pipeline engine nests it under\n// input.message.parsedEDI instead (confirmed by direct instrumentation\n// against a real Test Pipeline run; this project's own prior finding\n// documents the same \"message.\" prefix requirement for fhir.build/hl7.build\n// sourcePath strings, and it turns out to apply here too). Prefer that real\n// shape; fall back to the bare top-level key for Go-level test harnesses\n// that construct { parsedEDI: ... } directly without a \"message\" wrapper\n// (as every *_fhir_builder_test.go and edi_837_real_parser_roundtrip_test.go\n// fixture in this codebase already does).\nvar parsed = (input.message && input.message.parsedEDI) || input.parsedEDI || {};\nvar loops = parsed.loops || {};\n\n// edi.parse's own \"transactionSet\" config key is NOT read by the executor\n// (services/executors/transform/edi_parse_executor.go's ediParseConfig has\n// no such field) -- the real variant resolution happens inside the parser\n// via the composite ST01+GS08 lookup (edi/loop_engine.go), keyed off the\n// FILE's own real GS08, not any step config. A stray 837I file landing in\n// this professional-only mailbox would otherwise silently run through this\n// SV1-shaped derive logic and produce wrong/incomplete Claim resources with\n// no error. Guard explicitly instead.\nif (parsed.transactionSet !== \"837P\") {\n  return ({ _claim_contexts: [], _coverage_contexts: [], _billing_providers: [] });\n}\n\nfunction arr(v) {\n  if (!v) return [];\n  return Array.isArray(v) ? v : [v];\n}\nfunction first(v) {\n  var a = arr(v);\n  return a.length > 0 ? a[0] : {};\n}\n\nfunction genderToFHIR(code) {\n  if (code === \"M\") return \"male\";\n  if (code === \"F\") return \"female\";\n  return \"unknown\";\n}\n\nfunction relationshipToFHIR(code) {\n  var map = { \"18\": \"self\", \"01\": \"spouse\", \"19\": \"child\", \"20\": \"employee\" };\n  return map[code] || \"other\";\n}\n\n// X12 837 allows MULTIPLE 2000A (Billing Provider) hierarchical levels in one\n// file -- e.g. a clearinghouse batching claims from several billing practices\n// into one interchange. Every real sample checked into this repo only ever\n// carries one, but the spec allows more, so every one is walked rather than\n// assumed away (the pre-fix version of this script used first(loops[\"2000A\"])\n// and silently attributed every claim in the file to whichever provider\n// happened to be listed first). id is NPI-anchored (the one identifier every\n// real billing provider carries) with a positional fallback only for the rare\n// NPI-less case -- flexible, not rigid, matching this script's own PAT01/SBR02\n// fallback convention elsewhere.\nfunction billingProviderId(npi, idx) {\n  return \"organization-billing-\" + (npi || String(idx + 1));\n}\nvar billingProviderLevels = arr(loops[\"2000A\"]);\nvar billingProviders = [];\nfor (var bpIdx = 0; bpIdx < billingProviderLevels.length; bpIdx++) {\n  var bpProviderLoop = (billingProviderLevels[bpIdx].loops || {})[\"2010AA\"] || {};\n  var bpNM1 = first(bpProviderLoop.NM1);\n  var bpNpi = bpNM1.identificationCode || \"\";\n  billingProviders.push({\n    id: billingProviderId(bpNpi, bpIdx),\n    npi: bpNpi,\n    name: bpNM1.nameLastOrOrganizationName || \"\"\n  });\n}\n\n// HI is maxUse \">1\" -- a claim can carry SEVERAL separate HI segment\n// occurrences at the same 2300 level (one per qualifier-group; see\n// edi/schemas/x12_005010/segments/HI.json's own maxUse-correction note for\n// why, found via testing against real, unedited samples), each with its own\n// up-to-12-entry codes[] repeat group. Flatten every occurrence's codes[]\n// into one combined list before filtering by qualifier.\nfunction allHICodes(hiList) {\n  var instances = arr(hiList);\n  var out = [];\n  for (var i = 0; i < instances.length; i++) {\n    var codes = (instances[i] && instances[i].codes) || [];\n    for (var j = 0; j < codes.length; j++) out.push(codes[j]);\n  }\n  return out;\n}\n\nfunction extractDiagnoses(codes) {\n  var out = [];\n  for (var i = 0; i < codes.length; i++) {\n    var c = (codes[i] && codes[i].code) || {};\n    if (!c.code) continue;\n    out.push({ code: c.code, sequence: out.length + 1 });\n  }\n  return out;\n}\n// NOTE: 837P's own HI never carries a Present-on-Admission indicator (that's\n// an institutional-only concept, see 837I's own extractDiagnoses), so no\n// on_admission key is ever added here -- unlike 837I, which does.\n\nfunction diagnosisPointers(sv1) {\n  var ptr = (sv1 && sv1.diagnosisCodePointer) || {};\n  var out = [];\n  [\"pointer1\", \"pointer2\", \"pointer3\", \"pointer4\"].forEach(function (key) {\n    if (ptr[key]) out.push(parseInt(ptr[key], 10));\n  });\n  return out;\n}\n\nfunction extractServiceLines(claimLoops) {\n  var lines = arr((claimLoops || {})[\"2400\"]);\n  var out = [];\n  for (var i = 0; i < lines.length; i++) {\n    var line = lines[i];\n    var lx = line.LX || {};\n    var sv1 = line.SV1 || {};\n    var proc = sv1.procedureCode || {};\n    var dtpList = arr(line.DTP);\n    var svc = resolveServicedDate(dtpList);\n    out.push({\n      sequence: parseInt(lx.assignedNumber || String(i + 1), 10),\n      procedure_code: proc.code || \"\",\n      procedure_system: (proc.qualifier === \"HC\") ? \"http://www.ama-assn.org/go/cpt\" : \"\",\n      quantity: sv1.serviceUnitCount ? Number(sv1.serviceUnitCount) : 1,\n      net: sv1.lineItemChargeAmount ? Number(sv1.lineItemChargeAmount) : 0,\n      serviced_date: svc.servicedDate,\n      serviced_start: svc.servicedStart,\n      serviced_end: svc.servicedEnd,\n      diagnosis_pointers: diagnosisPointers(sv1)\n    });\n  }\n  return out;\n}\n\n// DTP02 (Date/Time Period Format Qualifier) \"D8\" is a single CCYYMMDD date;\n// \"RD8\" is a CCYYMMDD-CCYYMMDD range. Claim.item.serviced[x] is a choice type\n// (servicedDate | servicedPeriod) -- only one of the two shapes below is ever\n// populated per DTP*472 occurrence, matching that choice. Found only by\n// testing against a real, unedited 837 sample (databricks-industry-\n// solutions/x12-edi-parser's own CC_837P_EDI.txt/CC_837I_EDI.txt test\n// fixtures) carrying genuine RD8 ranges -- the synthetic Go-test fixture\n// only ever used D8 dates, so this gap was invisible there.\nfunction resolveServicedDate(dtpList) {\n  for (var d = 0; d < dtpList.length; d++) {\n    if (dtpList[d].dateTimeQualifier !== \"472\") continue;\n    var period = dtpList[d].datePeriod || \"\";\n    if (dtpList[d].dateTimePeriodFormatQualifier === \"RD8\" && period.indexOf(\"-\") !== -1) {\n      var parts = period.split(\"-\");\n      return { servicedDate: \"\", servicedStart: parts[0] || \"\", servicedEnd: parts[1] || \"\" };\n    }\n    return { servicedDate: period, servicedStart: \"\", servicedEnd: \"\" };\n  }\n  return { servicedDate: \"\", servicedStart: \"\", servicedEnd: \"\" };\n}\n\n// Covers every 2310A-F role that is genuinely a CARE TEAM MEMBER (a person or\n// organization providing care) -- 2310A Referring (DN), 2310B Rendering\n// (82), 2310D Supervising (DQ). 2310C Service Facility Location (77) is a\n// PLACE, not a care team member -- mapped separately to Claim.facility (see\n// extractFacility below), matching the base FHIR R4 Claim resource's own\n// dedicated 0..1 Reference field for exactly this concept. 2310E/2310F\n// Ambulance Pick-up/Drop-off Location (PW/45) are also genuinely locations\n// (addresses, not provider entities) with no equivalent base-Claim field --\n// a named, deliberate gap, not modeled in this pass. Found via X12.org's own\n// official COB example (Example 3a), whose 2310C carried a real NPI that a\n// prior version of this function silently dropped entirely.\n// Provider identification prefers NM1's own NPI (identificationCodeQualifier\n// \"XX\"), but real, spec-compliant claims sometimes carry NO NM1 identifier at\n// all for a pre-NPI-era provider, identifying them via a SEPARATE REF segment\n// instead (e.g. REF*1G = Provider UPIN Number) -- confirmed directly against\n// X12.org's own official \"Jones Hospital\" 837I example (same shape applies to\n// 837P's own 2310A/B/D). Previously this NM1-only check silently produced an\n// EMPTY care team for exactly this real, non-fabricated case. The REF\n// qualifier itself (1G/0B/G2/...) is carried through as part of the\n// identifier system URI rather than assumed to always be UPIN, since any of\n// several secondary qualifiers are possible here per the base X12 REF01 code\n// list.\nfunction providerIdentifier(entity) {\n  if (entity.identificationCode) {\n    return { identifier_system: \"http://hl7.org/fhir/sid/us-npi\", identifier_value: entity.identificationCode };\n  }\n  var ref = first(entity.REF);\n  if (ref.referenceIdentification) {\n    return {\n      identifier_system: \"http://ezhealthkonnect.local/x12-ref-qualifier/\" + (ref.referenceIdentificationQualifier || \"unknown\"),\n      identifier_value: ref.referenceIdentification\n    };\n  }\n  return null;\n}\n\nfunction extractCareTeam(claimLoops) {\n  var team = [];\n  var roleLoops = [\n    { key: \"2310A\", role: \"referring\" },\n    { key: \"2310B\", role: \"rendering\" },\n    { key: \"2310D\", role: \"supervising\" }\n  ];\n  for (var r = 0; r < roleLoops.length; r++) {\n    var list = arr((claimLoops || {})[roleLoops[r].key]);\n    for (var i = 0; i < list.length; i++) {\n      var nm1 = first(list[i].NM1);\n      var ident = providerIdentifier({ identificationCode: nm1.identificationCode, REF: list[i].REF });\n      if (ident) {\n        team.push({ identifier_system: ident.identifier_system, identifier_value: ident.identifier_value, role: roleLoops[r].role, sequence: team.length + 1 });\n      }\n    }\n  }\n  return team;\n}\n\n// Claim.facility (base FHIR R4, 0..1 Reference) -- \"Facility where the\n// services were provided.\" A logical (identifier-only) reference, same\n// pattern as careTeam[].provider -- no separate Location resource is built,\n// same rationale as the careTeam design note above.\nfunction extractFacility(claimLoops) {\n  var loop = (claimLoops || {})[\"2310C\"];\n  if (!loop) return {};\n  var nm1 = first(loop.NM1);\n  if (!nm1.identificationCode) return {};\n  return { facility_npi: nm1.identificationCode, facility_name: nm1.nameLastOrOrganizationName || \"\" };\n}\n\n// X12 837's claim-level loop 2320 (Other Subscriber Information, repeat up to\n// 10) carries additional payers beyond the primary (2010BB) for Coordination\n// of Benefits -- the actual other payer's identity lives on the nested 2330B\n// (Other Payer Name) sub-loop's own NM1. 2330A (Other Subscriber Name) and\n// 2330C-G (the other payer's own referring/rendering/service-facility/\n// supervising/billing providers) are not modeled in this pass -- named\n// simplification, matching this codebase's own \"core fields, not exhaustive\"\n// precedent. A row with no real payer identifier is skipped, same convention\n// extractCareTeam already uses. Sequence/priority is taken from encountered\n// order (2320 occurrences are, in practice, always listed in priority order\n// by real trading partners), not SBR01's own priority code -- reading that\n// too would add complexity for a case this codebase's real samples never\n// exercise.\nfunction extractOtherPayers(claimLoops) {\n  var out = [];\n  var list = arr((claimLoops || {})[\"2320\"]);\n  for (var i = 0; i < list.length; i++) {\n    var payerNM1 = first(((list[i].loops || {})[\"2330B\"] || {}).NM1);\n    if (!payerNM1.identificationCode) continue;\n    out.push({ payer_id: payerNM1.identificationCode, payer_name: payerNM1.nameLastOrOrganizationName || \"\" });\n  }\n  return out;\n}\n\n// Builds Claim.insurance[] rows AND the flattened per-payer Coverage-resource\n// rows from the SAME id formula in one pass, so the two stay correlated by\n// construction instead of via two independently-maintained computations\n// (mirroring this codebase's own established \"same derived/fixed id on both\n// sides\" pattern, e.g. the Da Vinci PAS template's Organization/Practitioner\n// correlation). The primary payer's own coverage_id (\"coverage-\" +\n// patientControlNumber) is UNCHANGED from this script's pre-COB shape -- only\n// secondary/tertiary payers get a \"-2\"/\"-3\"/... suffix -- so an existing\n// single-payer claim keeps producing the exact same Coverage id it always has.\nfunction buildInsuranceAndCoverage(payerInfo, patientInfo, subscriberInfo, claimLoops, pcn) {\n  var baseId = \"coverage-\" + pcn;\n  var insuranceList = [{ sequence: 1, focal: true, coverage_id: baseId }];\n  var coverageRows = [{\n    patient_info: patientInfo, subscriber_info: subscriberInfo, payer_info: payerInfo,\n    coverage_id: baseId, sequence: 1, focal: true\n  }];\n  var others = extractOtherPayers(claimLoops);\n  for (var i = 0; i < others.length; i++) {\n    var seq = i + 2;\n    var cid = baseId + \"-\" + seq;\n    insuranceList.push({ sequence: seq, focal: false, coverage_id: cid });\n    coverageRows.push({\n      patient_info: patientInfo, subscriber_info: subscriberInfo,\n      payer_info: { name: others[i].payer_name, payer_id: others[i].payer_id },\n      coverage_id: cid, sequence: seq, focal: false\n    });\n  }\n  return { insurance_list: insuranceList, coverage_rows: coverageRows };\n}\n\n// Claim.created is required by the base FHIR R4 Claim resource but has no\n// X12 837 equivalent (837 carries no \"claim record created\" timestamp) --\n// the same \"record processing time, not sourced from the message\" default\n// convention BHT03/BHT04 (creation date/time) already establish for the\n// interchange itself. Computed once for the whole file, not per claim.\nvar nowISO = new Date().toISOString();\n\n// NOTE: the returned object's own property names are snake_case throughout\n// (patient_info, total_charge_amount, etc.), NOT the camelCase a reader might\n// expect from the rest of this script's own internal variable names. This is\n// REQUIRED, not a style choice: a later fhir.build step can only reach this\n// enrichment.script's own return value via the \"steps.<alias>.step_output.<key>\"\n// reference path (BaseExecutor.SetStepOutputWithDetails stashes it in\n// inputData[\"_stepOutput\"], which executeStepWithContext extracts into that\n// per-step snapshot and then deletes from what actually flows forward as\n// plain inputData -- it never reaches a later step at the top level or under\n// \"message\"). That snapshot is ALWAYS passed through\n// models.OutputNormalizer.NormalizeStepOutput first, which snake_cases every\n// key it doesn't already recognize as snake_case -- so a later step's own\n// sourcePath/rowsPath config strings (see claim837PBuildConfig et al.) MUST\n// address these fields by their post-normalization names. Matching that\n// reality here, instead of writing camelCase and forcing every config\n// sourcePath to reference a silently-renamed key, is what keeps the script\n// and the config it feeds honest about what data shape actually flows\n// between them. Found only by a real browser Test-Pipeline run -- the\n// Go-level tests' own svcInjectStepOutput helper happens to preserve\n// whatever casing the script returns unchanged, so a camelCase/snake_case\n// mismatch here was invisible there.\nfunction buildClaimContext(patientInfo, subscriberInfo, payerInfo, claimLoop, billingProviderId) {\n  var clm = claimLoop.CLM || {};\n  var svcLoc = clm.healthCareServiceLocation || {};\n  var facility = extractFacility(claimLoop.loops);\n  var pcn = clm.patientControlNumber || \"\";\n  var insCov = buildInsuranceAndCoverage(payerInfo, patientInfo, subscriberInfo, claimLoop.loops, pcn);\n  var claim = {\n    patient_control_number: pcn,\n    total_charge_amount: clm.totalClaimChargeAmount ? Number(clm.totalClaimChargeAmount) : 0,\n    place_of_service_code: svcLoc.placeOfServiceCode || \"\",\n    created_at: nowISO,\n    billing_provider_id: billingProviderId,\n    diagnosis_list: extractDiagnoses(allHICodes(claimLoop.HI)),\n    service_lines: extractServiceLines(claimLoop.loops),\n    care_team: extractCareTeam(claimLoop.loops),\n    insurance_list: insCov.insurance_list\n  };\n  if (facility.facility_npi) {\n    claim.facility_npi = facility.facility_npi;\n    claim.facility_name = facility.facility_name;\n  }\n  return {\n    context: {\n      patient_info: patientInfo,\n      subscriber_info: subscriberInfo,\n      payer_info: payerInfo,\n      claim: claim\n    },\n    coverage_rows: insCov.coverage_rows\n  };\n}\n\nfunction personFromNM1AndDMG(nm1, dmg, relationshipCode) {\n  var gender = dmg.genderCode || \"\";\n  return {\n    first_name: nm1.nameFirst || \"\",\n    last_name: nm1.nameLastOrOrganizationName || \"\",\n    member_id: nm1.identificationCode || \"\",\n    dob: dmg.birthDate || \"\",\n    gender_fhir: genderToFHIR(gender),\n    relationship_code: relationshipCode || \"\",\n    relationship_fhir: relationshipToFHIR(relationshipCode || \"\")\n  };\n}\n\nvar claimContexts = [];\nvar coverageContexts = [];\n\nfunction pushClaimContext(built) {\n  claimContexts.push(built.context);\n  for (var cr = 0; cr < built.coverage_rows.length; cr++) coverageContexts.push(built.coverage_rows[cr]);\n}\n\nfor (var bp = 0; bp < billingProviderLevels.length; bp++) {\n  var bpId = billingProviders[bp].id;\n  var billingLoops = billingProviderLevels[bp].loops || {};\n  var subscriberLevels = arr(billingLoops[\"2000B\"]);\n  for (var s = 0; s < subscriberLevels.length; s++) {\n    var subLevel = subscriberLevels[s];\n    var subLoops = subLevel.loops || {};\n    var sbr = subLevel.SBR || {};\n\n    var subNM1 = first((subLoops[\"2010BA\"] || {}).NM1);\n    var subDMG = (subLoops[\"2010BA\"] || {}).DMG || {};\n    var subscriberInfo = personFromNM1AndDMG(subNM1, subDMG, \"18\");\n\n    var payerNM1 = first((subLoops[\"2010BB\"] || {}).NM1);\n    var payerInfo = {\n      name: payerNM1.nameLastOrOrganizationName || \"\",\n      payer_id: payerNM1.identificationCode || \"\"\n    };\n\n    var dependentLevels = arr(subLoops[\"2000C\"]);\n    if (dependentLevels.length > 0) {\n      for (var d = 0; d < dependentLevels.length; d++) {\n        var depLevel = dependentLevels[d];\n        var depLoops = depLevel.loops || {};\n        var depNM1 = first((depLoops[\"2010CA\"] || {}).NM1);\n        var depDMG = (depLoops[\"2010CA\"] || {}).DMG || {};\n        var depPAT = depLevel.PAT || {};\n        // Real, spec-compliant 837 data carries the dependent's own relationship\n        // code on PAT01 (2000C) -- confirmed against X12.org's own official\n        // \"Ben Kildare Service\" 837P example, which leaves the subscriber's own\n        // SBR02 (2000B) BLANK whenever a 2000C dependent loop exists and puts\n        // the real value on PAT01 instead (HL*2...SBR*P**2222-SJ*******CI [SBR02\n        // blank] -> HL*3...PAT*19 [child]). Prefer PAT01; fall back to SBR02 for\n        // trading partners that populate it there instead (flexible, not rigid).\n        var patientInfo = personFromNM1AndDMG(depNM1, depDMG, depPAT.individualRelationshipCode || sbr.individualRelationshipCode);\n        if (!patientInfo.member_id) patientInfo.member_id = subscriberInfo.member_id + \"-DEP\" + (d + 1);\n\n        var depClaims = arr(depLoops[\"2300\"]);\n        for (var dc = 0; dc < depClaims.length; dc++) {\n          pushClaimContext(buildClaimContext(patientInfo, subscriberInfo, payerInfo, depClaims[dc], bpId));\n        }\n      }\n    } else {\n      var subClaims = arr(subLoops[\"2300\"]);\n      for (var sc = 0; sc < subClaims.length; sc++) {\n        pushClaimContext(buildClaimContext(subscriberInfo, subscriberInfo, payerInfo, subClaims[sc], bpId));\n      }\n    }\n  }\n}\n\nreturn ({\n  _claim_contexts: claimContexts,\n  _coverage_contexts: coverageContexts,\n  _billing_providers: billingProviders\n});\n"},"enabled":true,"required":true,"sequence":201,"step_name":"Derive 837P Claim Contexts","step_type":"enrichment.script","step_alias":"derive_837p_claim_contexts","description":"Pure data reshaping only -- no FHIR resource-shape or profile knowledge. Flattens 837P's nested billing-provider/subscriber/dependent/claim/service-line/diagnosis structure into one flat array (_claim_contexts) so the fhir.build steps below can build one Patient/Coverage/Claim resource per claim declaratively via rowsPath, with no control.loop wrapper step needed."},{"config":{"fields":[{"sourcePath":"id","targetPath":"id"},{"targetPath":"active","literalValue":"true"},{"targetPath":"identifier[0].system","literalValue":"http://hl7.org/fhir/sid/us-npi"},{"sourcePath":"npi","targetPath":"identifier[0].value"},{"sourcePath":"name","targetPath":"name"}],"profile":"base","version":"R4","rowsPath":"steps.derive_837p_claim_contexts.step_output._billing_providers","outputField":"message.fhirOrganizations_837p","resourceType":"Organization"},"enabled":true,"required":true,"sequence":202,"step_name":"Build Organization","step_type":"fhir.build","step_alias":"build_organization_fhir_837p","description":"Builds one FHIR Organization resource per distinct 2000A billing provider found in the file (rowsPath mode) -- id is NPI-anchored (organization-billing-<npi>), referenced by each claim's own Claim.provider via its 