payor[0].identifier.value"},{"sourcePath":"payer_info.name","targetPath":"payor[0].display"}],"profile":"base","version":"R4","rowsPath":"steps.derive_837p_claim_contexts.step_output._coverage_contexts","outputField":"message.fhirCoverages_837p","resourceType":"Coverage"},"enabled":true,"required":true,"sequence":204,"step_name":"Build Coverage","step_type":"fhir.build","step_alias":"build_coverage_fhir_837p","description":"Builds one FHIR Coverage resource per claim x payer pair (rowsPath mode) -- a claim with a COB secondary payer gets its own second Coverage, since Claim.insurance[].coverage references a distinct Coverage per payor relationship. coverage_id is pre-computed per row by the derive script. subscriber.reference is only written when the patient IS the subscriber (relationshipCode 18) -- otherwise it would dangle, since no separate Patient resource is built for the subscriber in the dependent case; subscriberId (a plain string) is always populated regardless."},{"config":{"fields":[{"valueMap":{"prefix":"claim-"},"transform":"string_prefix","sourcePath":"claim.patient_control_number","targetPath":"id"},{"targetPath":"identifier[0].system","literalValue":"http://ezhealthkonnect.local/x12-claim-control-number"},{"sourcePath":"claim.patient_control_number","targetPath":"identifier[0].value"},{"targetPath":"status","literalValue":"active"},{"targetPath":"type.coding[0].system","literalValue":"http://terminology.hl7.org/CodeSystem/claim-type"},{"targetPath":"type.coding[0].code","literalValue":"professional"},{"targetPath":"use","literalValue":"claim"},{"sourcePath":"claim.created_at","targetPath":"created"},{"targetPath":"priority.coding[0].system","literalValue":"http://terminology.hl7.org/CodeSystem/processpriority"},{"targetPath":"priority.coding[0].code","literalValue":"normal"},{"valueMap":{"prefix":"Patient/"},"transform":"string_prefix","sourcePath":"patient_info.member_id","targetPath":"patient.reference"},{"valueMap":{"prefix":"Organization/"},"tra